window.CARDS=window.CARDS||{};CARDS["story-v-y0-index"]=[{"i":"sc-ayanokouji-atsuomi-y0-p10-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-atsuomi","q":"ayanokoji atsuomi a life carved out of disparity and ambition atsuomi reflects on his origins in his own monologue   born poor  uneducated and in the countryside  with nothing but youth and an  indefinitely expanding ambition   rich  poor the disparity of wealth   this japan is a society of disparities   while i understood that principle  i possessed nothing   i was born in the countryside  extremely poor  and so uneducated it was pitiful   it was an indefinitely expanding  ambition one that couldn t be suppressed   i will definitely rise and stand at the pinnacle of this country  defines himself by disparity and a single  suppressless ambition to reach the pinnacle of the country   the only support he had in life  frames the whole volume as his monologue looking back on the path that led to the white room","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p10-1\">A life carved out of disparity and ambition<\/a><\/span><span class=\"meta\">Side stories · p.10–11<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Atsuomi reflects on his origins in his own monologue — born poor, uneducated and in the countryside, with nothing but youth and an &quot;indefinitely expanding ambition.&quot;<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;RICH, POOR—THE DISPARITY of wealth.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;This Japan is a society of disparities.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;While I understood that principle, I possessed nothing.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I was born in the countryside, extremely poor, and so uneducated it was pitiful.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;It was an indefinitely expanding &#x27;ambition&#x27;—one that couldn&#x27;t be suppressed.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I will definitely rise and stand at the pinnacle of this country.&quot;<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Defines himself by disparity and a single, suppressless ambition to reach the pinnacle of the country — the only support he had in life.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Backstory<\/span> Frames the whole volume as his monologue looking back on the path that led to the White Room.<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p11-1\">→ After: The failed election and the backroom rise<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p11-1","v":"y0","y":0,"o":36,"k":"narration","w":"naoe-sensei ayanokouji-atsuomi","q":"ayanokoji atsuomi the failed election and the backroom rise  at twenty five  i gained my first right to be elected   it was a fleeting  foolish dream  i underestimated the election and was miserably defeated   what was important in winning an election was which organization you belonged to and whom you followed   i requested to join the ruling  citizens  party  and began my steps as a politician   i took on the dirty backroom jobs that nobody wanted to do   eventually  as a secret blade for  naoe sensei  who controlled many factions within the citizens  party  i unhesitatingly delved into any wrongdoing facilitating underage girls  giving bribes  and committing espionage against rival organizations   at the age of thirty six  i had one foot in the realm of power  pragmatic and utterly unscrupulous   learns that power  not ideals  wins elections and becomes naoe sensei s  secret blade  committing any wrongdoing for advancement  becomes his secret blade  regards him as a stepping stone to be eventually surpassed and crushed","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p11-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p11-1\">The failed election and the backroom rise<\/a><\/span><span class=\"meta\">Side stories · p.11–12<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;At twenty-five, I gained my first right to be elected.&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;It was a fleeting, foolish dream. I underestimated the election and was miserably defeated.&quot;<span class=\"pg\">p.11<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;What was important in winning an election was which organization you belonged to and whom you followed.&quot;<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I requested to join the ruling &#x27;Citizens&#x27; Party&#x27; and began my steps as a politician.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I took on the dirty backroom jobs that nobody wanted to do.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Eventually, as a secret blade for &#x27;Naoe-sensei,&#x27; who controlled many factions within the Citizens&#x27; Party, I unhesitatingly delved into any wrongdoing—facilitating underage girls, giving bribes, and committing espionage against rival organizations.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;At the age of thirty-six, I had one foot in the realm of power.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Pragmatic and utterly unscrupulous — learns that power, not ideals, wins elections and becomes Naoe-sensei&#x27;s &quot;secret blade,&quot; committing any wrongdoing for advancement.<span class=\"pg\">p.11–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Becomes his secret blade; regards him as a stepping stone to be eventually surpassed and crushed.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p10-1\">← Before: A life carved out of disparity and ambition<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p12-1\">→ After: The newborn and the White Room&#x27;s fourth phase<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p12-1","v":"y0","y":0,"o":36,"k":"narration","w":"tabuchi ayanokouji-kiyotaka ayanokouji-atsuomi","q":"ayanokoji atsuomi the newborn and the white room s fourth phase his child is born  he views the newborn with no emotion beyond relief at the political lever it represents   a newborn arrived  just one month old   no special emotions arose not a single one   if anything  i was relieved that the key to moving the higher ups had arrived   there are currently no issues  there were no problems found in various tests  including the brain waves    tabuchi s report  like the previous children  start the experiment immediately  coldly instrumental   sees his own son as a  key to moving the higher ups  feels nothing  and orders the experiment to begin at once  tabuchi runs the health dna tests and reports the results  atsuomi orders him to start the experiment  his newborn son  immediately entered into the white room experiment","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p12-1\">The newborn and the White Room&#x27;s fourth phase<\/a><\/span><span class=\"meta\">Side stories · p.12–13<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">His child is born; he views the newborn with no emotion beyond relief at the political lever it represents.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#tabuchi\">Tabuchi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;A newborn arrived, just one month old.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;No special emotions arose—not a single one.&quot;<span class=\"pg\">p.12<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;If anything, I was relieved that the key to moving the higher-ups had arrived.&quot;<span class=\"pg\">p.12<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;There are currently no issues. There were no problems found in various tests, including the brain waves.&quot; — Tabuchi&#x27;s report<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Like the previous children, start the experiment immediately.&#x27;&quot;<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Coldly instrumental — sees his own son as a &quot;key to moving the higher-ups,&quot; feels nothing, and orders the experiment to begin at once.<span class=\"pg\">p.12–13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tabuchi<\/b> Tabuchi runs the health/DNA tests and reports the results; Atsuomi orders him to start the experiment.<span class=\"pg\">p.12–13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His newborn son, immediately entered into the White Room experiment.<span class=\"pg\">p.12–13<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p11-1\">← Before: The failed election and the backroom rise<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p15-1\">→ After: The staged goodbye and the vow to reach the top<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p12-1","v":"y0","y":0,"o":36,"k":"","w":"ayanokouji-atsuomi tabuchi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka born into the white room a newborn  one month old  is first seen by atsuomi through the glass  the experiment starts immediately  he is one month old here and the scene is told entirely through atsuomi  the translation gives him no words  the farewell staged for the cameras  p 15  is fundraising material  not a real goodbye  after being taken away  the father closes his eyes alone  the white room s fourth phase begins without him knowing  the father who enters him into the white room  runs the newborn s tests and is ordered to start the experiment","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p12-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p12-1\">Born into the White Room<\/a><\/span><span class=\"meta\">Side stories · p.12–16<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">A newborn, one month old, is first seen by Atsuomi through the glass; the experiment starts immediately.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/index.html#tabuchi\">Tabuchi<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> He is one month old here and the scene is told entirely through Atsuomi; the translation gives him no words. The farewell staged for the cameras (p.15) is fundraising material, not a real goodbye.<span class=\"pg\">p.12–16<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After being taken away, the father closes his eyes alone; the White Room&#x27;s fourth phase begins without him knowing.<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> The father who enters him into the White Room.<span class=\"pg\">p.12–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tabuchi<\/b> Runs the newborn&#x27;s tests and is ordered to start the experiment.<span class=\"pg\">p.12–16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p131-1\">→ After: First memory: the pure white ceiling<\/button><\/div><\/article>"},{"i":"sc-tabuchi-y0-p12-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi ayanokouji-kiyotaka tabuchi","q":"tabuchi tabuchi  the newborn s tests  the staged farewell reports the newborn s test results to atsuomi  later startles when atsuomi orders a camera shoot instead of a real goodbye   there are currently no issues  there were no problems found in various tests  including the brain waves  the dna test results also matched  the exchange  health check completed     any problems  and the line  you can now have direct contact if you wish  are untagged in the translation  no speaker is assigned to them here   indeed  he s your son  sensei  a rigorous education awaits him  but the results will   uh  ah  yes  right  runs every pre experiment test on the newborn   brain waves  dna match   and reports in detail  atsuomi orders the experiment to begin immediately  without contact  the project head who orders him to start the experiment and briefs him on the staged farewell  the newborn subject  tabuchi runs the tests on him","h":"<article class=\"card\" id=\"sc-tabuchi-y0-p12-1\"><h3><span class=\"ttl\">Tabuchi: the newborn&#x27;s tests; the staged farewell<\/span><span class=\"meta\">Side stories · p.12–16<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#tabuchi\">Tabuchi<\/a><\/span><\/h3><p class=\"setup\">Reports the newborn&#x27;s test results to Atsuomi; later startles when Atsuomi orders a camera shoot instead of a real goodbye.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tabuchi<\/b> “There are currently no issues. There were no problems found in various tests, including the brain waves. The DNA test results also matched.”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tabuchi<\/b> “Indeed, he&#x27;s your son, Sensei. A rigorous education awaits him, but the results will—”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tabuchi<\/b> “Uh…? Ah, yes, right.”<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The exchange &quot;Health check completed.&quot; / &quot;Any problems?&quot; and the line &quot;You can now have direct contact if you wish.&quot; are untagged in the translation; no speaker is assigned to them here.<span class=\"pg\">p.12–13<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Runs every pre-experiment test on the newborn — brain waves, DNA match — and reports in detail.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Atsuomi orders the experiment to begin immediately, without contact.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> The project head who orders him to start the experiment and briefs him on the staged farewell.<span class=\"pg\">p.12–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The newborn subject; Tabuchi runs the tests on him.<span class=\"pg\">p.12–16<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p15-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka sakayanagi tabuchi naoe-sensei ayanokouji-atsuomi","q":"ayanokoji atsuomi the staged goodbye and the vow to reach the top holds his son through the glass before the white room  staging an emotional farewell for the cameras   this child is more important than my own life  and i m sending him to the white room  capture the determination and tension on camera   a parent who s indifferent about leaving their child  and a parent who reluctantly entrusts their child for the future   anyway  all the necessary preparations are now complete  connect me to sakayanagi   i would use anything  even my own child  discard it  and reach the top   even someone with absolute authority  like naoe sensei  was no different as a stepping stone   if you don t want to die  you better struggle on your own  kiyotaka   the turning point came about four years after i started working under naoe sensei  calculated and ruthless   stages a reluctant father image for fundraising  treats his child and naoe sensei alike as disposable stepping stones  and addresses kiyotaka with a parting challenge to survive alone  sends him to the white room as the fourth phase subject  tells him he must struggle on his own  requests to be connected to him once preparations are complete  directs him to capture the staged farewell on camera  resolves to eventually surpass and crush him","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p15-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p15-1\">The staged goodbye and the vow to reach the top<\/a><\/span><span class=\"meta\">Side stories · p.15–16<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Holds his son through the glass before the White Room, staging an emotional farewell for the cameras.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#tabuchi\">Tabuchi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;This child is more important than my own life, and I&#x27;m sending him to the White Room. Capture the determination and tension on camera.&#x27;&quot;<span class=\"pg\">p.15<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;A parent who&#x27;s indifferent about leaving their child, and a parent who reluctantly entrusts their child for the future.&quot;<span class=\"pg\">p.15<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Anyway, all the necessary preparations are now complete. Connect me to Sakayanagi.&#x27;&quot;<span class=\"pg\">p.15<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I would use anything, even my own child, discard it, and reach the top.&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Even someone with absolute authority, like Naoe-sensei, was no different as a stepping stone.&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;If you don&#x27;t want to die, you better struggle on your own, Kiyotaka.&#x27;&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;The turning point came about four years after I started working under Naoe-sensei.&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calculated and ruthless — stages a reluctant-father image for fundraising, treats his child and Naoe-sensei alike as disposable stepping stones, and addresses Kiyotaka with a parting challenge to survive alone.<span class=\"pg\">p.15–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sends him to the White Room as the fourth-phase subject; tells him he must struggle on his own.<span class=\"pg\">p.15–16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">sakayanagi<\/b> Requests to be connected to him once preparations are complete.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tabuchi<\/b> Directs him to capture the staged farewell on camera.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Resolves to eventually surpass and crush him.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p12-1\">← Before: The newborn and the White Room&#x27;s fourth phase<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p17-1\">→ After: Waiting for Naoe-sensei; on Kamogawa<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p17-1","v":"y0","y":0,"o":36,"k":"narration","w":"kamogawa naoe-sensei ayanokouji-atsuomi","q":"ayanokoji atsuomi waiting for naoe sensei  on kamogawa waits an hour in the freezing cold outside ryoutei sasagawa for naoe sensei  with kamogawa   it s always like this  for naoe sensei  the appointed time is merely a guideline   you re naive  we re lucky if he comes here today at all  oftentimes  he doesn t even show up   even being late is a weapon for naoe sensei  like the anecdote of miyamoto musashi at ganryujima   it would be troublesome if you look down on naoe sensei i ll just dismiss them like that   they say that seeking hardship is good  even if you have to pay for it  but i ve been hit once or twice  patient  loyal and world weary   treats naoe s lateness as deliberate power  absorbs the anger of those kept waiting  and despises the spoiled second generation politicians  manages and lectures the complaining rookie  sees him as a leech who wants only to survive  serves as his intermediary and shielding face  absorbing resentment so naoe never has to","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p17-1\">Waiting for Naoe-sensei; on Kamogawa<\/a><\/span><span class=\"meta\">Side stories · p.17–19<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Waits an hour in the freezing cold outside Ryoutei Sasagawa for Naoe-sensei, with Kamogawa.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;It&#x27;s always like this. For Naoe-sensei, the appointed time is merely a guideline.&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;You&#x27;re naive. We&#x27;re lucky if he comes here today at all. Oftentimes, he doesn&#x27;t even show up.&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Even being late is a weapon for Naoe-sensei. Like the anecdote of Miyamoto Musashi at Ganryujima.&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;It would be troublesome if you look down on Naoe-sensei—I&#x27;ll just dismiss them like that.&#x27;&quot;<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;They say that seeking hardship is good, even if you have to pay for it, but I&#x27;ve been hit once or twice.&#x27;&quot;<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Patient, loyal and world-weary — treats Naoe&#x27;s lateness as deliberate power, absorbs the anger of those kept waiting, and despises the spoiled second-generation politicians.<span class=\"pg\">p.17–19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Manages and lectures the complaining rookie; sees him as a leech who wants only to survive.<span class=\"pg\">p.17–19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Serves as his intermediary and shielding face, absorbing resentment so Naoe never has to.<span class=\"pg\">p.17–18<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p15-1\">← Before: The staged goodbye and the vow to reach the top<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p20-1\">→ After: Naoe arrives; the meeting with Asama<\/button><\/div><\/article>"},{"i":"sc-kamogawa-y0-p17-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka kamogawa-toshizou naoe-sensei kamogawa","q":"kamogawa the complaining rookie waiting in the cold waits with atsuomi in the freezing cold outside ryoutei sasagawa for naoe sensei   it s cold  isn t it  ayanokouji san  when will naoe sensei arrive   does that mean  at worst  he could even be one or two hours late   eeeeh  really  then how long are we going to wait for someone who might not arrive   my father didn t teach me anything   i was just taught to silently follow naoe sensei if i do that  i would be safe as a politician   i want to finish my groundwork quickly and get to the easy jobs   i m hungry too  on such a cold day  nothing beats hot sake   why not talk a little  sensei isn t around   i ve heard rumors  they say that people who work under naoe sensei are usually fast to become useless  but you re a treasured newcomer   you can relax your posture at least in this seat  naive  talkative and entitled   a second generation rookie who complains about the cold and hunger  wants the easy jobs  and is ignorant of the political world s iron rules  the  ayanokouji san  he waits with and peppers with questions  atsuomi finds him bothersome  his father  who taught him nothing and smoothed his path as a second generation politician  believes silently following him guarantees a safe  long career","h":"<article class=\"card\" id=\"sc-kamogawa-y0-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamogawa.html#sc-kamogawa-y0-p17-1\">The complaining rookie waiting in the cold<\/a><\/span><span class=\"meta\">Side stories · p.17–24<\/span><span class=\"by\">notes on <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/span><\/h3><p class=\"setup\">Waits with Atsuomi in the freezing cold outside Ryoutei Sasagawa for Naoe-sensei.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#kamogawa-toshizou\">Kamogawa Toshizou<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;It&#x27;s cold, isn&#x27;t it, Ayanokouji-san…? When will Naoe-sensei arrive…?&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;Does that mean, at worst, he could even be one or two hours late?&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;Eeeeh… Really…? Then how long are we going to wait for someone who might not arrive?&#x27;&quot;<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;My father didn&#x27;t teach me anything...&#x27;&quot;<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I was just taught to silently follow Naoe-sensei—if I do that, I would be safe as a politician.&#x27;&quot;<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I want to finish my groundwork quickly and get to the easy jobs.&#x27;&quot;<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;m hungry too… On such a cold day, nothing beats hot sake.&#x27;&quot;<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Why not talk a little? Sensei isn&#x27;t around.&#x27;&quot;<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;ve heard rumors. They say that people who work under Naoe-sensei are usually fast to become useless, but you&#x27;re a treasured newcomer.&#x27;&quot;<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;You can relax your posture at least in this seat.&#x27;&quot;<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Naive, talkative and entitled — a second-generation rookie who complains about the cold and hunger, wants the easy jobs, and is ignorant of the political world&#x27;s iron rules.<span class=\"pg\">p.17–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The &quot;Ayanokouji-san&quot; he waits with and peppers with questions; Atsuomi finds him bothersome.<span class=\"pg\">p.17–24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa Toshizou<\/b> His father, who taught him nothing and smoothed his path as a second-generation politician.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Believes silently following him guarantees a safe, long career.<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p24-1\">→ After: Seiza and the sake; a silhouette in the hallway<\/button><\/div><\/article>"},{"i":"sc-miyamoto-soshi-y0-p17-1","v":"y0","y":0,"o":36,"k":"","w":"miyamoto-soshi","q":"miyamoto soshi miyamoto soshi  mentioned  not present  the only  miyamoto  in this volume is the historical swordsman miyamoto musashi in atsuomi s ganryujima example   even being late is a weapon for naoe sensei  like the anecdote of miyamoto musashi at ganryujima    footnoted as the duel where musashi arrived three hours late  no mention anywhere of the class 1 d student miyamoto soshi  the roster s listing of this volume for him is a name collision  not an on page presence  passing mention only","h":"<article class=\"card\" id=\"sc-miyamoto-soshi-y0-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/miyamoto-soshi.html#sc-miyamoto-soshi-y0-p17-1\">Miyamoto Sōshi (mentioned)<\/a><\/span><span class=\"meta\">Side stories · p.17–18<\/span><span class=\"by\">notes on <a href=\"../../../people/miyamoto-soshi.html\">Miyamoto Soshi<\/a><\/span><\/h3><p class=\"setup\">Not present; the only &quot;Miyamoto&quot; in this volume is the historical swordsman Miyamoto Musashi in Atsuomi&#x27;s Ganryujima example.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Even being late is a weapon for Naoe-sensei. Like the anecdote of Miyamoto Musashi at Ganryujima.” — footnoted as the duel where Musashi arrived three hours late.<span class=\"pg\">p.17–18<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No mention anywhere of the Class 1-D student Miyamoto Sōshi; the roster&#x27;s listing of this volume for him is a name-collision, not an on-page presence.<span class=\"pg\">p.17–18<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.17<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kamogawa-toshizou-y0-p19-1","v":"y0","y":0,"o":36,"k":"","w":"kamogawa-toshizou","q":"kamogawa toshizou kamogawa toshizou  mentioned  not present  named as the father who taught kamogawa nothing and smoothed his path as a second generation politician   didn t representative kamogawa teach you the iron rules    atsuomi on the cold ryoutei wait   i m still kamogawa toshizou s son  you know    invoked to prove he can be useful  the banks would see through to him  not his son   my only regret is that i can t report today s achievements to my father  since he passed away last year    died of myocardial infarction  passing mention only","h":"<article class=\"card\" id=\"sc-kamogawa-toshizou-y0-p19-1\"><h3><span class=\"ttl\">Kamogawa Toshizou (mentioned)<\/span><span class=\"meta\">Side stories · p.19–199<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kamogawa-toshizou\">Kamogawa Toshizou<\/a><\/span><\/h3><p class=\"setup\">Not present; named as the father who taught Kamogawa nothing and smoothed his path as a second-generation politician.<\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Didn&#x27;t Representative Kamogawa teach you the iron rules?” — Atsuomi on the cold ryoutei wait.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I&#x27;m still Kamogawa Toshizou&#x27;s son, you know?” — invoked to prove he can be useful; the banks would see through to him, not his son.<span class=\"pg\">p.43–45<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “My only regret is that I can&#x27;t report today&#x27;s achievements to my father… since he passed away last year” — died of myocardial infarction.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.19<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p20-1","v":"y0","y":0,"o":36,"k":"narration","w":"asama kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi naoe arrives  the meeting with asama naoe s taxi arrives  atsuomi stops kamogawa from reacting rashly when a woman is seen with him   don t do anything rash   good work today  naoe sensei   where is asama   he s been waiting  i ll guide you   asama sensei  i ve brought naoe sensei  refuses the temptation to eavesdrop on the two major politicians   scheming would be exposed and end his career  vigilant and disciplined   shields naoe from embarrassment  reads the room  and withdraws rather than risk the  devil s  temptation to gather information  guides naoe to the waiting asama hisashi  notes the instant master servant role reversal  signals him to pay the fare and keeps him in line","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p20-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p20-1\">Naoe arrives; the meeting with Asama<\/a><\/span><span class=\"meta\">Side stories · p.20–23<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Naoe&#x27;s taxi arrives; Atsuomi stops Kamogawa from reacting rashly when a woman is seen with him.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#asama\">Asama<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Don&#x27;t do anything rash.&#x27;&quot;<span class=\"pg\">p.20<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Good work today, Naoe-sensei.&#x27;&quot;<span class=\"pg\">p.21<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Where is Asama?&#x27;&quot;<span class=\"pg\">p.21<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;He&#x27;s been waiting. I&#x27;ll guide you.&#x27;&quot;<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Asama-sensei, I&#x27;ve brought Naoe-sensei.&#x27;&quot;<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> Refuses the temptation to eavesdrop on the two major politicians — scheming would be exposed and end his career.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Vigilant and disciplined — shields Naoe from embarrassment, reads the room, and withdraws rather than risk the &quot;devil&#x27;s&quot; temptation to gather information.<span class=\"pg\">p.20–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asama<\/b> Guides Naoe to the waiting Asama Hisashi; notes the instant master-servant role reversal.<span class=\"pg\">p.21–22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Signals him to pay the fare and keeps him in line.<span class=\"pg\">p.20–21<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p17-1\">← Before: Waiting for Naoe-sensei; on Kamogawa<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p24-1\">→ After: The private room: seiza and the sake<\/button><\/div><\/article>"},{"i":"sc-naoe-y0-p20-1","v":"y0","y":0,"o":36,"k":"spoken","w":"asama ayanokouji-atsuomi kamogawa naoe","q":"naoe naoe arrives  the ryoutei steps out of the taxi with a young woman at his side  enters ryoutei sasagawa with the aura of a real power holder   where is asama   oh  good work   sorry to keep you waiting  asama  work has been hectic  naoe jinnosuke   minister of transport and minister of economy  trade  and industry in the past  now the citizens  party s secretary general  turning sixty eight  the real power holder  a step behind the prime minister in title only  receives him in the private room  his secretary general hands and fixer  keeps him out of naoe s way at the entrance","h":"<article class=\"card\" id=\"sc-naoe-y0-p20-1\"><h3><span class=\"ttl\"><a href=\"../../../people/naoe.html#sc-naoe-y0-p20-1\">Naoe arrives; the ryoutei<\/a><\/span><span class=\"meta\">Side stories · p.20–23<\/span><span class=\"by\">notes on <a href=\"../../../people/naoe.html\">Naoe<\/a><\/span><\/h3><p class=\"setup\">Steps out of the taxi with a young woman at his side; enters Ryoutei Sasagawa with the aura of a real power holder.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#asama\">Asama<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “Where is Asama?”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “Oh, good work!”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “Sorry to keep you waiting, Asama. Work has been hectic.”<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Naoe Jinnosuke — Minister of Transport and Minister of Economy, Trade, and Industry in the past; now the Citizens&#x27; Party&#x27;s secretary-general, turning sixty-eight; the real power holder, a step behind the prime minister in title only.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Asama<\/b> Receives him in the private room.<span class=\"pg\">p.21–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> His secretary-general hands and fixer.<span class=\"pg\">p.20–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Keeps him out of Naoe&#x27;s way at the entrance.<span class=\"pg\">p.20–21<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-naoe-y0-p27-1\">→ After: The Part 2 meeting: Isomaru, Kijima, and the envelope<\/button><\/div><\/article>"},{"i":"sc-asama-y0-p21-1","v":"y0","y":0,"o":36,"k":"spoken","w":"naoe asama","q":"asama asama  the deputy minister waits in formal seated position for naoe s party  stands and bows deeply when naoe is brought in   i ve been waiting for you  naoe sensei   i m aware of your busy schedule  asama hisashi  seventy one  three years older than naoe  deputy minister of the ministry of land  infrastructure  transport  and tourism  a key figure in the naoe faction  to atsuomi  asama seemed to live in a world beyond reach  the power difference switched instantly to master and servant  the conversation is off limits to everyone else  the party leader whose visit he receives","h":"<article class=\"card\" id=\"sc-asama-y0-p21-1\"><h3><span class=\"ttl\">Asama, the Deputy Minister<\/span><span class=\"meta\">Side stories · p.21–23<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#asama\">Asama<\/a><\/span><\/h3><p class=\"setup\">Waits in formal seated position for Naoe&#x27;s party; stands and bows deeply when Naoe is brought in.<\/p><p class=\"with\">with <a href=\"../../../people/naoe.html\">Naoe<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Asama<\/b> “I&#x27;ve been waiting for you, Naoe-sensei.”<span class=\"pg\">p.22<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Asama<\/b> “I&#x27;m aware of your busy schedule.”<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Asama Hisashi, seventy-one, three years older than Naoe; Deputy Minister of the Ministry of Land, Infrastructure, Transport, and Tourism; a key figure in the Naoe faction.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> To Atsuomi, Asama seemed to live in a world beyond reach; the power difference switched instantly to master and servant; the conversation is off-limits to everyone else.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Naoe<\/b> The party leader whose visit he receives.<span class=\"pg\">p.21–23<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p24-1","v":"y0","y":0,"o":36,"k":"narration","w":"kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi the private room  seiza and the sake in a separate private room with kamogawa  warns him not to drink the ceremonial sake   don t drink the sake   are you planning to send off naoe sensei with the smell of alcohol  this is nothing more than a formality   it s a habit  in front of naoe sensei and the others  i have to sit in seiza for hours without any trouble  abstains from sake after witnessing a predecessor erased for it  and keeps himself in seiza always so formal occasions cost him nothing  teaches him the room s unspoken rules","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p24-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p24-1\">The private room: seiza and the sake<\/a><\/span><span class=\"meta\">Side stories · p.24–26<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">In a separate private room with Kamogawa, warns him not to drink the ceremonial sake.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Don&#x27;t drink the sake.&#x27;&quot;<span class=\"pg\">p.24<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Are you planning to send off Naoe-sensei with the smell of alcohol? This is nothing more than a formality.&#x27;&quot;<span class=\"pg\">p.24<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;It&#x27;s a habit. In front of Naoe-sensei and the others, I have to sit in seiza for hours without any trouble.&#x27;&quot;<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Abstains from sake after witnessing a predecessor erased for it, and keeps himself in seiza always so formal occasions cost him nothing.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Teaches him the room&#x27;s unspoken rules.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p20-1\">← Before: Naoe arrives; the meeting with Asama<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p27-1\">→ After: Naoe&#x27;s summons: Kijima and the project envelope<\/button><\/div><\/article>"},{"i":"sc-kamogawa-y0-p24-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi kijima kamogawa","q":"kamogawa seiza and the sake  a silhouette in the hallway sits in the lower seat  boasts about sake brands  is told off  and spots an unfamiliar suited silhouette in the corridor   you can relax your posture at least in this seat   e eh  but there s delicious looking sake right in front of me  what is this brand  i ve never seen it in a pub   that s tough  in the hallway  a distinctly recognizable back passes   atsuomi identifies it as kijima sensei  kamogawa pays the taxi fare and neither speaks of it","h":"<article class=\"card\" id=\"sc-kamogawa-y0-p24-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamogawa.html#sc-kamogawa-y0-p24-1\">Seiza and the sake; a silhouette in the hallway<\/a><\/span><span class=\"meta\">Side stories · p.24–26<\/span><span class=\"by\">notes on <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/span><\/h3><p class=\"setup\">Sits in the lower seat; boasts about sake brands, is told off, and spots an unfamiliar suited silhouette in the corridor.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/index.html#kijima\">Kijima<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “You can relax your posture at least in this seat.”<span class=\"pg\">p.24<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “E-Eh? But there&#x27;s delicious-looking sake right in front of me. What is this brand? I&#x27;ve never seen it in a pub.”<span class=\"pg\">p.24<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “That&#x27;s tough...”<span class=\"pg\">p.25<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> In the hallway, a distinctly recognizable back passes — Atsuomi identifies it as Kijima-sensei; Kamogawa pays the taxi fare and neither speaks of it.<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> <span class=\"pg\">p.24–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kijima<\/b> <span class=\"pg\">p.25–26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p17-1\">← Before: The complaining rookie waiting in the cold<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p27-1\">→ After: The envelope; the Human Resource Development Project<\/button><\/div><\/article>"},{"i":"sc-isomaru-y0-p25-1","v":"y0","y":0,"o":36,"k":"","w":"isomaru","q":"isomaru isomaru youkou  mentioned  not present  named as the chair of the citizens  party s third highest position and a rival faction head   unaligned with the other three major factions belonging to naoe sensei  isomaru sensei  and prime minister miyako   isomaru youkou had been reigning in the political world as the citizens  party s third highest ranking position for many years    naoe  passing mention only","h":"<article class=\"card\" id=\"sc-isomaru-y0-p25-1\"><h3><span class=\"ttl\">Isomaru Youkou (mentioned)<\/span><span class=\"meta\">Side stories · p.25–29<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#isomaru\">Isomaru<\/a><\/span><\/h3><p class=\"setup\">Not present; named as the chair of the Citizens&#x27; Party&#x27;s third-highest position and a rival faction head.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “unaligned with the other three major factions belonging to Naoe-sensei, Isomaru-sensei, and Prime Minister Miyako.”<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Isomaru Youkou had been reigning in the political world as the Citizens&#x27; Party&#x27;s third highest-ranking position for many years.” — Naoe.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.25<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-miyako-y0-p25-1","v":"y0","y":0,"o":36,"k":"","w":"miyako","q":"miyako prime minister miyako  mentioned  not present  named only as the head of the citizens  party under whom naoe ranked second   the other three major factions belonging to naoe sensei  isomaru sensei  and prime minister miyako   under prime minister miyako  naoe sensei was number two  isomaru sensei number three  and kijima sensei  a young politician  was number four  they were indeed contenders for the next prime minister s seat  passing mention only","h":"<article class=\"card\" id=\"sc-miyako-y0-p25-1\"><h3><span class=\"ttl\">Prime Minister Miyako (mentioned)<\/span><span class=\"meta\">Side stories · p.25–29<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#miyako\">Miyako<\/a><\/span><\/h3><p class=\"setup\">Not present; named only as the head of the Citizens&#x27; Party under whom Naoe ranked second.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “the other three major factions belonging to Naoe-sensei, Isomaru-sensei, and Prime Minister Miyako.”<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Under Prime Minister Miyako, Naoe-sensei was number two, Isomaru-sensei number three, and Kijima-sensei, a young politician, was number four. They were indeed contenders for the next prime minister&#x27;s seat.”<span class=\"pg\">p.28–29<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.25<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p27-1","v":"y0","y":0,"o":36,"k":"narration","w":"naoe-sensei kijima isomaru ayanokouji-atsuomi","q":"ayanokoji atsuomi naoe s summons  kijima and the project envelope summoned by naoe after the meeting to another private room  with kijima s untouched cups evident   this is my fourth year studying under you  sensei   i m truly thankful  naoe sensei  you picked up someone like me   i believe he has many achievements  but if there s something to highlight  it would be  anhs   you must be joking  whether it s the present or future  the only person i will learn from is you  naoe sensei  carefully deferential   deflects naoe s praise  declares loyalty  and correctly identifies kijima s anhs as his rise  views him as the  have not  who rose fastest  naoe probes his loyalty and hints at a new project  identified by naoe as the greatest enemy  a young  clean  spotlight politician rising on anhs  naoe s rival  the third ranking party figure   old fashioned and straightforward","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p27-1\">Naoe&#x27;s summons: Kijima and the project envelope<\/a><\/span><span class=\"meta\">Side stories · p.27–30<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Summoned by Naoe after the meeting to another private room, with Kijima&#x27;s untouched cups evident.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#kijima\">Kijima<\/a> · <a href=\"../../../people/index.html#isomaru\">Isomaru<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;This is my fourth year studying under you, Sensei.&#x27;&quot;<span class=\"pg\">p.27<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;I&#x27;m truly thankful, Naoe-sensei. You picked up someone like me.&#x27;&quot;<span class=\"pg\">p.28<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;I believe he has many achievements, but if there&#x27;s something to highlight, it would be &#x27;ANHS&#x27;.&#x27;&quot;<span class=\"pg\">p.29<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;You must be joking. Whether it&#x27;s the present or future, the only person I will learn from is you, Naoe-sensei.&#x27;&quot;<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Carefully deferential — deflects Naoe&#x27;s praise, declares loyalty, and correctly identifies Kijima&#x27;s ANHS as his rise.<span class=\"pg\">p.27–30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Views him as the &quot;have-not&quot; who rose fastest; Naoe probes his loyalty and hints at a new project.<span class=\"pg\">p.27–30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kijima<\/b> Identified by Naoe as the greatest enemy; a young, clean, spotlight politician rising on ANHS.<span class=\"pg\">p.28–29<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Isomaru<\/b> Naoe&#x27;s rival, the third-ranking party figure — old-fashioned and straightforward.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p24-1\">← Before: The private room: seiza and the sake<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p31-1\">→ After: &quot;What makes a politician outstanding&quot;<\/button><\/div><\/article>"},{"i":"sc-kamogawa-y0-p27-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi naoe kijima kamogawa","q":"kamogawa the envelope  the human resource development project led into another private room where untouched bowls betray kijima s prior presence  struggles to follow naoe s questions   e eh   someone who  responds to the citizens  wishes  maybe   a government run educational institution from infancy  i ve never heard of such a thing   ah  thank you very much   how  i m not sure how to respond   um  i was wondering  are there parents who would leave their infants and children at educational facilities  it doesn t seem to be very feasible  unless kidnapping is involved  isn t it impossible   but why was naoe sensei taking a taxi today  and he was openly friendly with a woman in that taxi  wasn t he  i m not even going to talk about the age difference  but doesn t he look like he s cheating   it s an amazing project  but it s turned into something unbelievable  sweat forms on his forehead during the conversation about kijima  he cannot respond to the envelope s contents  forced to work with him as second fiddle  his patron  also the one who keeps him as a shackle","h":"<article class=\"card\" id=\"sc-kamogawa-y0-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamogawa.html#sc-kamogawa-y0-p27-1\">The envelope; the Human Resource Development Project<\/a><\/span><span class=\"meta\">Side stories · p.27–41<\/span><span class=\"by\">notes on <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/span><\/h3><p class=\"setup\">Led into another private room where untouched bowls betray Kijima&#x27;s prior presence; struggles to follow Naoe&#x27;s questions.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/naoe.html\">Naoe<\/a> · <a href=\"../../../people/index.html#kijima\">Kijima<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “E-Eh!?”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “Someone who… responds to the citizens&#x27; wishes… maybe?”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamogawa<\/b> “A government-run educational institution from infancy? I&#x27;ve never heard of such a thing.”<span class=\"pg\">p.34<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Ah, thank you very much!”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How…? I&#x27;m not sure how to respond.”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “um, I was wondering… are there parents who would leave their infants and children at educational facilities? It doesn&#x27;t seem to be very feasible... unless kidnapping is involved, isn&#x27;t it impossible?”<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But why was Naoe-sensei taking a taxi today? And he was openly friendly with a woman in that taxi, wasn&#x27;t he? I&#x27;m not even going to talk about the age difference, but doesn&#x27;t he look like he&#x27;s cheating?”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s an amazing project… but it&#x27;s turned into something unbelievable.”<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Sweat forms on his forehead during the conversation about Kijima; he cannot respond to the envelope&#x27;s contents.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Forced to work with him as second fiddle.<span class=\"pg\">p.27–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Naoe<\/b> His patron; also the one who keeps him as a shackle.<span class=\"pg\">p.27–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kijima<\/b> <span class=\"pg\">p.25–35<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p24-1\">← Before: Seiza and the sake; a silhouette in the hallway<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p43-1\">→ After: The shabby office; sent to find a facility<\/button><\/div><\/article>"},{"i":"sc-naoe-y0-p27-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi kamogawa kijima tsukishiro naoe","q":"naoe the part 2 meeting  isomaru  kijima  and the envelope summons atsuomi and kamogawa after asama s audience  discusses isomaru  then kijima  and finally hands over the human resource development plan   ayanokouji  how long has it been since you started working under me   however  your abilities still aren t fully recognized within the party   today s discussion  as you might ve guessed  was about isomaru   i think he s the greatest enemy we need to be wary of   children s education is inseparably linked to the country s development  it s well received by supporters  despite being an enemy  i admire the interesting ideas he s come up with   young party members tend to blindly believe in him   i thought i d check if you were one of them   actually  today  i ve decided to officially start a project that was being considered behind the scenes   this project could significantly impact my political career  not only isomaru  but kijima and the opposition are gradually gaining ground  it s time to make a move   i ask the both of you  what makes a politician exceptionally outstanding  kamogawa  answer   that s quite a good description   i hope you can put that idea into practice with your own hands someday   take a look   japan s standard of education is only declining  we need to implement education that looks not only five or ten years ahead of our time  but twenty to thirty years into the future   politicians need to focus on education  even if they have no interest  it connects to votes and support both domestically and internationally   you need to have a more flexible mind  kamogawa   that s right  yes  but even if we use the same solution for that issue  the process used to reach it can greatly change how it s perceived  we ll have to diligently put in the work while avoiding unnecessary attention   of course  that s my intention  there s a man named sakayanagi who has connections in political and financial circles  he s about your age  a young man  but he s discreet and trustworthy  you should try contacting him   also  i have something important to tell you  don t expect any financial support from me   well then  i m counting on you  ayanokouji   ayanokouji is a promising politician  it wouldn t hurt to greet him   this guy  well  to put it simply  he s a jack of all trades  if you have any trouble  you should rely on tsukishiro  he s about your age  but he s quite capable  tests his loyalty and binds him to the project by coercion in all but name  assigns him as atsuomi s subordinate on the project  unreservedly calls him the greatest enemy  delivers him with the briefing on his two roles","h":"<article class=\"card\" id=\"sc-naoe-y0-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/naoe.html#sc-naoe-y0-p27-1\">The Part 2 meeting: Isomaru, Kijima, and the envelope<\/a><\/span><span class=\"meta\">Side stories · p.27–41<\/span><span class=\"by\">notes on <a href=\"../../../people/naoe.html\">Naoe<\/a><\/span><\/h3><p class=\"setup\">Summons Atsuomi and Kamogawa after Asama&#x27;s audience; discusses Isomaru, then Kijima, and finally hands over the Human Resource Development Plan.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a> · <a href=\"../../../people/index.html#kijima\">Kijima<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “Ayanokouji, how long has it been since you started working under me?”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “However, your abilities still aren&#x27;t fully recognized within the party.”<span class=\"pg\">p.28<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Naoe<\/b> “Today&#x27;s discussion, as you might&#x27;ve guessed, was about Isomaru.”<span class=\"pg\">p.28<\/span><\/li><\/ul><details class=\"more\"><summary>23 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I think he&#x27;s the greatest enemy we need to be wary of.”<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Children&#x27;s education is inseparably linked to the country&#x27;s development. It&#x27;s well-received by supporters. Despite being an enemy, I admire the interesting ideas he&#x27;s come up with.”<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Young party members tend to blindly believe in him.”<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought I&#x27;d check if you were one of them.”<span class=\"pg\">p.29<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Actually, today, I&#x27;ve decided to officially start a project that was being considered behind the scenes.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This project could significantly impact my political career. Not only Isomaru, but Kijima and the opposition are gradually gaining ground. It&#x27;s time to make a move.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I ask the both of you, what makes a politician exceptionally outstanding? Kamogawa, answer.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s quite a good description.”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hope you can put that idea into practice with your own hands someday.”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Take a look.”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Japan&#x27;s standard of education is only declining. We need to implement education that looks not only five or ten years ahead of our time, but twenty to thirty years into the future.”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Politicians need to focus on education. Even if they have no interest, it connects to votes and support both domestically and internationally.”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You need to have a more flexible mind, Kamogawa.”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. Yes, but even if we use the same solution for that issue, the process used to reach it can greatly change how it&#x27;s perceived. We&#x27;ll have to diligently put in the work while avoiding unnecessary attention.”<span class=\"pg\">p.35<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, that&#x27;s my intention. There&#x27;s a man named Sakayanagi who has connections in political and financial circles. He&#x27;s about your age, a young man, but he&#x27;s discreet and trustworthy. You should try contacting him.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Also, I have something important to tell you: don&#x27;t expect any financial support from me.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well then, I&#x27;m counting on you, Ayanokouji.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji is a promising politician. It wouldn&#x27;t hurt to greet him.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “This guy, well, to put it simply, he&#x27;s a jack-of-all-trades. If you have any trouble, you should rely on Tsukishiro. He&#x27;s about your age, but he&#x27;s quite capable.”<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Tests his loyalty and binds him to the project by coercion in all but name.<span class=\"pg\">p.27–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Assigns him as Atsuomi&#x27;s subordinate on the project.<span class=\"pg\">p.27–40<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kijima<\/b> Unreservedly calls him the greatest enemy.<span class=\"pg\">p.28–33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Delivers him with the briefing on his two roles.<span class=\"pg\">p.38–41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-naoe-y0-p20-1\">← Before: Naoe arrives; the ryoutei<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p31-1","v":"y0","y":0,"o":36,"k":"narration","w":"naoe-sensei kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi  what makes a politician outstanding  naoe poses a drinking game question to kamogawa and atsuomi   although i m inexperienced  i think of someone like you  naoe sensei   a bad politician serves tempura to a customer who wants sushi   a customer is a customer  sometimes they are the citizens  sometimes they are politicians  and sometimes they are something else altogether   a good politician serves delicious sushi to a customer who wants sushi  probably  only about thirty percent  no  maybe only twenty percent of politicians can do this   if you re going to call a politician  exceptionally outstanding  more is required  even if a customer wants sushi  they can guide them to be fully satisfied with curry or beef bowl   when i had just started studying under you  naoe sensei  you once told me that people s actions are determined by their goals   i will devote my whole heart and soul to this task  articulate and ambitious   defines a truly outstanding politician as one who can redirect desire to a satisfying alternative  then accepts naoe s envelope project with a bow  knowing failure would ash his four years  challenges and delights him with the sushi metaphor  accepts the envelope project that promises fame  watches him give a simplistic answer about responding to the citizens  wishes","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p31-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p31-1\">&quot;What makes a politician outstanding&quot;<\/a><\/span><span class=\"meta\">Side stories · p.31–33<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Naoe poses a drinking-game question to Kamogawa and Atsuomi.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Although I&#x27;m inexperienced, I think of someone like you, Naoe-sensei.&#x27;&quot;<span class=\"pg\">p.31<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;A bad politician serves tempura to a customer who wants sushi.&#x27;&quot;<span class=\"pg\">p.31<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;A customer is a customer. Sometimes they are the citizens, sometimes they are politicians, and sometimes they are something else altogether.&#x27;&quot;<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;A good politician serves delicious sushi to a customer who wants sushi. Probably, only about thirty percent... no, maybe only twenty percent of politicians can do this.&#x27;&quot;<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;If you&#x27;re going to call a politician &#x27;exceptionally outstanding,&#x27; more is required. Even if a customer wants sushi, they can guide them to be fully satisfied with curry or beef bowl.&#x27;&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;When I had just started studying under you, Naoe-sensei, you once told me that people&#x27;s actions are determined by their goals.&#x27;&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I will devote my whole heart and soul to this task.&#x27;&quot;<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Articulate and ambitious — defines a truly outstanding politician as one who can redirect desire to a satisfying alternative, then accepts Naoe&#x27;s envelope project with a bow, knowing failure would ash his four years.<span class=\"pg\">p.31–33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Challenges and delights him with the sushi metaphor; accepts the envelope project that promises fame.<span class=\"pg\">p.31–33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Watches him give a simplistic answer about responding to the citizens&#x27; wishes.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p27-1\">← Before: Naoe&#x27;s summons: Kijima and the project envelope<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p33-1\">→ After: The Human Resource Development Plan<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p33-1","v":"y0","y":0,"o":36,"k":"narration","w":"kamogawa naoe sakayanagi-narimori tsukishiro ayanokouji-atsuomi","q":"ayanokoji atsuomi the human resource development plan takes the brown envelope from naoe    human resource development plan  provisional    and accepts the assignment in all but name   japan s standard of education is only declining  we need to implement education that looks not only five or ten years ahead of our time  but twenty to thirty years into the future   politicians need to focus on education  even if they have no interest  it connects to votes and support both domestically and internationally   it s a valid question  can you answer that  ayanokouji   naoe   of course  i will accept it   this is a top secret project  it isn t at the stage where we can inform others about it   also  i have something important to tell you  don t expect any financial support from me  naoe s framing  use abandoned and illegitimate children  provide government backed education  and route them into the political world as obedient servants sharing business tycoons  blood  the financial liaison named is a sakayanagi    the sakayanagi i m talking about has a son that s who i meant  kamogawa is deliberately kept by his side  atsuomi suspects it as a deliberate shackle","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p33-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p33-1\">The Human Resource Development Plan<\/a><\/span><span class=\"meta\">Side stories · p.33–41<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Takes the brown envelope from Naoe — “Human Resource Development Plan (Provisional)” — and accepts the assignment in all but name.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a> · <a href=\"../../../people/naoe.html\">Naoe<\/a> · <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> “Japan&#x27;s standard of education is only declining. We need to implement education that looks not only five or ten years ahead of our time, but twenty to thirty years into the future.”<span class=\"pg\">p.33<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> “Politicians need to focus on education. Even if they have no interest, it connects to votes and support both domestically and internationally.”<span class=\"pg\">p.33<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> “It&#x27;s a valid question. Can you answer that, Ayanokouji?” (Naoe)<span class=\"pg\">p.35<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> “Of course, I will accept it.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “This is a top-secret project. It isn&#x27;t at the stage where we can inform others about it.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Also, I have something important to tell you: don&#x27;t expect any financial support from me.”<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Naoe&#x27;s framing: use abandoned and illegitimate children, provide government-backed education, and route them into the political world as obedient servants sharing business tycoons&#x27; blood.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The financial liaison named is a Sakayanagi — “the Sakayanagi I&#x27;m talking about has a son—that&#x27;s who I meant.”<span class=\"pg\">p.37–38<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kamogawa is deliberately kept by his side; Atsuomi suspects it as a deliberate shackle.<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> <span class=\"pg\">p.34–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Naoe<\/b> <span class=\"pg\">p.33–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> <span class=\"pg\">p.37–38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> <span class=\"pg\">p.38–41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p31-1\">← Before: &quot;What makes a politician outstanding&quot;<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p42-1\">→ After: Planning the Human Resource Development Project; using Kamogawa<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y0-p38-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi naoe tsukishiro","q":"tsukishiro the introduction   tsukishiro tokinari  approaches atsuomi in the corridor with a faint  unwavering smile  gives his business card   my name is tsukishiro tokinari  unfortunately  i am not a bodyguard  but i look forward to working with you   from personal security to information gathering  i will do whatever is necessary  naoe introduces him as  a jack of all trades  who works with any client   not merely naoe s employee  the opposition s peace party is in his orbit too","h":"<article class=\"card\" id=\"sc-tsukishiro-y0-p38-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y0-p38-1\">The introduction: &quot;Tsukishiro Tokinari&quot;<\/a><\/span><span class=\"meta\">Side stories · p.38–41<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><p class=\"setup\">Approaches Atsuomi in the corridor with a faint, unwavering smile; gives his business card.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/naoe.html\">Naoe<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “My name is Tsukishiro Tokinari. Unfortunately, I am not a bodyguard, but I look forward to working with you.”<span class=\"pg\">p.39<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> “From personal security to information gathering, I will do whatever is necessary.”<span class=\"pg\">p.39<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Naoe introduces him as &quot;a jack-of-all-trades&quot; who works with any client — not merely Naoe&#x27;s employee; the opposition&#x27;s Peace Party is in his orbit too.<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> <span class=\"pg\">p.38–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Naoe<\/b> <span class=\"pg\">p.38–40<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y0-p78-1\">→ After: Tsukishiro&#x27;s meeting: observer, cleanup man, negotiator<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p42-1","v":"y0","y":0,"o":36,"k":"narration","w":"kamogawa ooba naoe-sensei ayanokouji-atsuomi","q":"ayanokoji atsuomi planning the human resource development project  using kamogawa at his cluttered office  plans the  human resource development project    gathering newborns and securing a huge budget   this project is going to be troublesome   it s me  put ooba on  i have a new job for him   kamogawa  i m telling you this for your own good  don t mimic the likes of kisarazu   i m not saying don t buy real estate  i m just saying don t miss the right timing  money is finite  but it holds infinite possibilities   can you be of use   for the project in question  it s essential to secure an experimental facility  i ll leave the location selection to you   from a budgetary perspective  seems like it ll inevitably be in the countryside   there are more than a few construction companies that would have its dirt revealed when dug into  ruthlessly pragmatic   uses whatever pieces work regardless of morality  contacts the criminal ooba group to acquire newborns  and manipulates kamogawa with small praise into useful service  puts him to work selecting a facility location and securing funding  knows a little praise makes him useful  contacts him about acquiring newborns   evil means are unavoidable  notes naoe could make funds appear with one word  since he can t  a major investor is urgently needed","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p42-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p42-1\">Planning the Human Resource Development Project; using Kamogawa<\/a><\/span><span class=\"meta\">Side stories · p.42–47<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">At his cluttered office, plans the &quot;Human Resource Development Project&quot; — gathering newborns and securing a huge budget.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a> · <a href=\"../../../people/index.html#ooba\">Ooba<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;…This project is going to be troublesome.&quot;<span class=\"pg\">p.42<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;It&#x27;s me. Put Ooba on. I have a new job for him.&#x27;&quot;<span class=\"pg\">p.42<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Kamogawa. I&#x27;m telling you this for your own good, don&#x27;t mimic the likes of Kisarazu.&#x27;&quot;<span class=\"pg\">p.44<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;m not saying don&#x27;t buy real estate. I&#x27;m just saying don&#x27;t miss the right timing. Money is finite, but it holds infinite possibilities.&#x27;&quot;<span class=\"pg\">p.44<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Can you be of use?&#x27;&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;For the project in question, it&#x27;s essential to secure an experimental facility. I&#x27;ll leave the location selection to you.&#x27;&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;From a budgetary perspective, seems like it&#x27;ll inevitably be in the countryside.&#x27;&quot;<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;There are more than a few construction companies that would have its dirt revealed when dug into.&#x27;&quot;<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ruthlessly pragmatic — uses whatever pieces work regardless of morality, contacts the criminal Ooba group to acquire newborns, and manipulates Kamogawa with small praise into useful service.<span class=\"pg\">p.42–47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Puts him to work selecting a facility location and securing funding; knows a little praise makes him useful.<span class=\"pg\">p.42–47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ooba<\/b> Contacts him about acquiring newborns — evil means are unavoidable.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Notes Naoe could make funds appear with one word; since he can&#x27;t, a major investor is urgently needed.<span class=\"pg\">p.45–47<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p33-1\">← Before: The Human Resource Development Plan<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p48-1\">→ After: Visiting Sakayanagi Narimori for funding<\/button><\/div><\/article>"},{"i":"sc-kamogawa-y0-p43-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka kamogawa-toshizou kamogawa","q":"kamogawa the shabby office  sent to find a facility visits atsuomi s shabby office and is shocked by how he lives   are you perhaps living in this office  ayanokouji san  it kind of smells like it s been lived in   my colleague kisarazu san  who is three years older than me  boasted about how he signed a contract for the top floor of a tower   eh  a hundred million yen  i d save about ninety million  and spend ten million on fun stuff  like going to hostess clubs or buying a car   i m here to help you  ayanokouji san  just as naoe sensei instructed   i ll show you i can be  after all  i m still kamogawa toshizou s son  you know   is that so  naive and extravagant minded   envies kisarazu s tower mansion  would blow windfalls on hostess clubs  and is easily excited by being given a  significant role  assigned by him to select a facility location  eager to prove himself  invokes his father s name to claim he can be useful","h":"<article class=\"card\" id=\"sc-kamogawa-y0-p43-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamogawa.html#sc-kamogawa-y0-p43-1\">The shabby office; sent to find a facility<\/a><\/span><span class=\"meta\">Side stories · p.43–46<\/span><span class=\"by\">notes on <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/span><\/h3><p class=\"setup\">Visits Atsuomi&#x27;s shabby office and is shocked by how he lives.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#kamogawa-toshizou\">Kamogawa Toshizou<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;Are you perhaps living in this office, Ayanokouji-san? It kind of smells like it&#x27;s been lived in…&#x27;&quot;<span class=\"pg\">p.43<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;My colleague Kisarazu-san, who is three years older than me, boasted about how he signed a contract for the top floor of a tower.&#x27;&quot;<span class=\"pg\">p.43<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;Eh? A hundred million yen? I&#x27;d save about ninety million, and spend ten million on fun stuff, like going to hostess clubs or buying a car.&#x27;&quot;<span class=\"pg\">p.44<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;m here to help you, Ayanokouji-san, just as Naoe-sensei instructed.&#x27;&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;ll show you I can be. After all, I&#x27;m still Kamogawa Toshizou&#x27;s son, you know?&#x27;&quot;<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Is that so?&#x27;&quot;<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Naive and extravagant-minded — envies Kisarazu&#x27;s tower mansion, would blow windfalls on hostess clubs, and is easily excited by being given a &quot;significant role.&quot;<span class=\"pg\">p.43–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Assigned by him to select a facility location; eager to prove himself.<span class=\"pg\">p.43–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa Toshizou<\/b> Invokes his father&#x27;s name to claim he can be useful.<span class=\"pg\">p.45<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p27-1\">← Before: The envelope; the Human Resource Development Project<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p70-1\">→ After: Reporting the facility complete; the interviews<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p48-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-atsuomi","q":"ayanokoji atsuomi visiting sakayanagi narimori for funding visits the sakayanagi mansion in shirokane to ask for help funding the project   nice to meet you  my name is ayanokouji  thank you for making time in your busy schedule   i recalled naoe sensei saying that if i ever had a problem  i could rely on you  sakayanagi san that s why i ve come to visit  sakayanagi narimori  arisu s father  receives him   slender  gentle  feigning humility  he says naoe spoke highly of ayanokouji and that they are the same age  his own lines are recorded on his own card  confident but mannerly   chooses to sit without making himself small  while knowing he is the one asking a favor","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p48-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p48-1\">Visiting Sakayanagi Narimori for funding<\/a><\/span><span class=\"meta\">Side stories · p.48–49<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Visits the Sakayanagi mansion in Shirokane to ask for help funding the project.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Nice to meet you. My name is Ayanokouji. Thank you for making time in your busy schedule.&quot;<span class=\"pg\">p.48<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;I recalled Naoe-sensei saying that if I ever had a problem, I could rely on you, Sakayanagi-san—that&#x27;s why I&#x27;ve come to visit.&#x27;&quot;<span class=\"pg\">p.49<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Sakayanagi Narimori (Arisu&#x27;s father) receives him — slender, gentle, feigning humility. He says Naoe spoke highly of Ayanokouji and that they are the same age. His own lines are recorded on his own card.<span class=\"pg\">p.48–49<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Confident but mannerly — chooses to sit without making himself small, while knowing he is the one asking a favor.<span class=\"pg\">p.48–49<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p42-1\">← Before: Planning the Human Resource Development Project; using Kamogawa<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p70-1\">→ After: The White Room facility named; the mentor&#x27;s warning<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-narimori-y0-p49-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-kiyotaka naoe-sensei sakayanagi-arisu kijima sakayanagi-narimori","q":"sakayanagi narimori sakayanagi narimori weighs atsuomi s proposal receives atsuomi in his family s shirokane mansion  a slender  gentle man who feigns humility   i m sakayanagi  i ve heard about you  ayanokouji sensei  several times from naoe sensei   not at all  i was told you re a very capable person  moreover  when i heard that we re the same age  i felt quite embarrassed   no  i still have a long way to go  it was just my father who was remarkable  that s really all there is to it   i see  you re not asking for investment money  then   you don t know whether i m on kijima sensei s side  naoe sensei s side  or neutral  yet  you re willing to share such information with me   many politicians will sooner or later join some faction  no matter which faction  once you decide to support someone in particular  you must believe in them to the end without any doubt   i respect my father  but at the same time  i see him as a goal   indeed  hundreds of children are abandoned every year in japan   however  even so  you re a diet member  ayanokouji sensei  you re someone who should confront and fight with the country   don t lie  expose all of your thoughts and objectives  polished  cautious and probing   tests atsuomi s loyalties  refuses flattery  empathizes with abandoned children yet calls it the government s problem  and finally agrees to read the proposal after sensing his passion and conviction  receives his pitch  agrees to act as liaison to the financial world  holds a principle of fully trusting him  deliberately approached him to learn from a rival to kijima  his daughter  the  remarkable  father she refers to is him   see note  his father is close with kijima  but he distances himself by learning from naoe  in saying his father was remarkable  he means his own father  arisu s grandfather  the anhs founder  arisu refers to narimori as her remarkable father  the family chain is  grandfather  anhs founder    narimori   arisu","h":"<article class=\"card\" id=\"sc-sakayanagi-narimori-y0-p49-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-narimori.html#sc-sakayanagi-narimori-y0-p49-1\">Sakayanagi Narimori weighs Atsuomi&#x27;s proposal<\/a><\/span><span class=\"meta\">Side stories · p.49–54<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/span><\/h3><p class=\"setup\">Receives Atsuomi in his family&#x27;s Shirokane mansion; a slender, gentle man who feigns humility.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/index.html#kijima\">Kijima<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;I&#x27;m Sakayanagi. I&#x27;ve heard about you, Ayanokouji-sensei, several times from Naoe-sensei.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;Not at all. I was told you&#x27;re a very capable person. Moreover, when I heard that we&#x27;re the same age, I felt quite embarrassed.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;No, I still have a long way to go. It was just my father who was remarkable. That&#x27;s really all there is to it.&quot;<span class=\"pg\">p.49<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I see. You&#x27;re not asking for investment money, then.&quot;<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You don&#x27;t know whether I&#x27;m on Kijima-sensei&#x27;s side, Naoe-sensei&#x27;s side, or neutral. Yet, you&#x27;re willing to share such information with me?&quot;<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Many politicians will sooner or later join some faction. No matter which faction, once you decide to support someone in particular, you must believe in them to the end without any doubt.&quot;<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I respect my father, but at the same time, I see him as a goal.&quot;<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Indeed, hundreds of children are abandoned every year in Japan.&quot;<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;However… even so, you&#x27;re a Diet member, Ayanokouji-sensei. You&#x27;re someone who should confront and fight with the country.&quot;<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Don&#x27;t lie. Expose all of your thoughts and objectives.&quot;<span class=\"pg\">p.54<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Polished, cautious and probing — tests Atsuomi&#x27;s loyalties, refuses flattery, empathizes with abandoned children yet calls it the government&#x27;s problem, and finally agrees to read the proposal after sensing his passion and conviction.<span class=\"pg\">p.49–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Receives his pitch; agrees to act as liaison to the financial world.<span class=\"pg\">p.49–54<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Holds a principle of fully trusting him; deliberately approached him to learn from a rival to Kijima.<span class=\"pg\">p.49–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> His daughter; the &quot;remarkable&quot; father she refers to is him — see note.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kijima<\/b> His father is close with Kijima, but he distances himself by learning from Naoe.<span class=\"pg\">p.50–51<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> In saying his father was remarkable, he means his own father (Arisu&#x27;s grandfather, the ANHS founder); Arisu refers to Narimori as her remarkable father. The family chain is: grandfather (ANHS founder) → Narimori → Arisu.<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-narimori-y0-p101-1\">→ After: Sakayanagi&#x27;s assessment and objection<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p70-1","v":"y0","y":0,"o":36,"k":"narration","w":"kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi the white room facility named  the mentor s warning reviews photos of the finished facility in saitama  kamogawa reports construction complete   we ll call it white room  we want to emphasize white s purity in the image   there are more than a few construction companies that would have its dirt revealed when dug into   kamogawa  i need to teach you something important  the world of politics isn t just about friends or foes   never mind  it seems it was too soon for you  sees the  white room  name as image strategy  knows he walks a bridge that could collapse and tries  in vain  to warn the naive kamogawa  credits him for moving the financial world  judges him not yet ready to understand political danger","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p70-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p70-1\">The White Room facility named; the mentor&#x27;s warning<\/a><\/span><span class=\"meta\">Side stories · p.70–71<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Reviews photos of the finished facility in Saitama; Kamogawa reports construction complete.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;We&#x27;ll call it White Room. We want to emphasize white&#x27;s purity in the image.&#x27;&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;There are more than a few construction companies that would have its dirt revealed when dug into.&#x27;&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Kamogawa, I need to teach you something important. The world of politics isn&#x27;t just about friends or foes.&#x27;&quot;<span class=\"pg\">p.71<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Never mind. It seems it was too soon for you.&#x27;&quot;<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sees the &quot;White Room&quot; name as image strategy; knows he walks a bridge that could collapse and tries (in vain) to warn the naive Kamogawa.<span class=\"pg\">p.70–71<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Credits him for moving the financial world; judges him not yet ready to understand political danger.<span class=\"pg\">p.70–71<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p48-1\">← Before: Visiting Sakayanagi Narimori for funding<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p72-1\">→ After: Hiring Souya and the other &quot;problem&quot; experts<\/button><\/div><\/article>"},{"i":"sc-kamogawa-y0-p70-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka kamogawa","q":"kamogawa reporting the facility complete  the interviews  all construction is completed   but to rebuild it so beautifully with that budget  normally  it would cost nearly double the amount   it s all thanks to you  ayanokouji san for moving the people within the financial world  raising nearly four hundred million in one night is no small feat   white room  i see  it s simple  but it s nice and clear   ah  it s over  i m more tired than i thought  admiring and out of his depth   impressed by the funding and the white room name  exhausted by the interviews  and worried about the questionable hires  reports to him and accompanies the interviews","h":"<article class=\"card\" id=\"sc-kamogawa-y0-p70-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kamogawa.html#sc-kamogawa-y0-p70-1\">Reporting the facility complete; the interviews<\/a><\/span><span class=\"meta\">Side stories · p.70–76<\/span><span class=\"by\">notes on <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;All construction is completed.&#x27;&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;But to rebuild it so beautifully with that budget… Normally, it would cost nearly double the amount.&#x27;&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kamogawa<\/b> &quot;&#x27;It&#x27;s all thanks to you, Ayanokouji-san—for moving the people within the financial world. Raising nearly four hundred million in one night is no small feat.&#x27;&quot;<span class=\"pg\">p.70<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;White Room… I see, it&#x27;s simple, but it&#x27;s nice and clear.&#x27;&quot;<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Ah, it&#x27;s over… I&#x27;m more tired than I thought.&#x27;&quot;<span class=\"pg\">p.76<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Admiring and out of his depth — impressed by the funding and the White Room name, exhausted by the interviews, and worried about the questionable hires.<span class=\"pg\">p.70–76<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Reports to him and accompanies the interviews.<span class=\"pg\">p.70–76<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kamogawa-y0-p43-1\">← Before: The shabby office; sent to find a facility<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p72-1","v":"y0","y":0,"o":36,"k":"narration","w":"souya kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi hiring souya and the other  problem  experts interviews souya  a disgraced former doctor  for the research lab   i haven t told you that you re hired yet   i don t care about your career   which university you graduated from  which hospital you worked at  what crimes you ve committed i have no interest in any of that   i m only interested in your current thoughts and abilities   i ll give you a chance to resurrect yourself   he has no close associates around him  he s obsessed with money and doesn t seek honor from the outside world   we ll let the people we hire compete  then  the answers will naturally emerge  coldly exploitative   hires competent outcasts who can be paid and controlled  pits experts against each other to reveal ability  and fires without mercy if results disappoint  hires him on the spot as a researcher former doctor to manage the subjects  lets him observe  dismisses his worries about hiring such people","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p72-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p72-1\">Hiring Souya and the other &quot;problem&quot; experts<\/a><\/span><span class=\"meta\">Side stories · p.72–75<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Interviews Souya, a disgraced former doctor, for the research lab.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#souya\">Sōya<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;I haven&#x27;t told you that you&#x27;re hired yet.&#x27;&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;I don&#x27;t care about your career.&#x27;&quot;<span class=\"pg\">p.73<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Which university you graduated from, which hospital you worked at, what crimes you&#x27;ve committed—I have no interest in any of that.&#x27;&quot;<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;m only interested in your current thoughts and abilities.&#x27;&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I&#x27;ll give you a chance to resurrect yourself.&#x27;&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;He has no close associates around him. He&#x27;s obsessed with money and doesn&#x27;t seek honor from the outside world.&#x27;&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;We&#x27;ll let the people we hire compete. Then, the answers will naturally emerge.&#x27;&quot;<span class=\"pg\">p.75<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Coldly exploitative — hires competent outcasts who can be paid and controlled, pits experts against each other to reveal ability, and fires without mercy if results disappoint.<span class=\"pg\">p.72–75<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sōya<\/b> Hires him on the spot as a researcher/former doctor to manage the subjects.<span class=\"pg\">p.72–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Lets him observe; dismisses his worries about hiring such people.<span class=\"pg\">p.72–75<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p70-1\">← Before: The White Room facility named; the mentor&#x27;s warning<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p76-1\">→ After: Tsukishiro: the journalist&#x27;s body and the background check<\/button><\/div><\/article>"},{"i":"sc-souya-y0-p72-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka kamogawa souya","q":"soya the disgraced doctor s interview arrives for the research lab interview in a lab coat   thank you very much  ayanokouji san  i never thought a stray researcher like me would be approached by such a great person   i couldn t very well come naked  could i   isn t that a trivial matter  my formal attire is a lab coat  so i see no problem  i d rather you see it as a sign of my seriousness   i can generally understand people just by looking at them  that hasn t changed even now   regret  i m not regretting anything  even now  when i think about why those around me betrayed me  it just makes me furious   thank you very much  i will definitely meet your expectations  eccentric  unrepentant and gifted   wears a lab coat as  formal attire  prides himself on reading people  bears no regret for his past crimes  and is hired on the spot  is interviewed and hired by him to manage and grow the white room subjects  his lab coat and attitude prompt kamogawa s worried questions","h":"<article class=\"card\" id=\"sc-souya-y0-p72-1\"><h3><span class=\"ttl\">The disgraced doctor&#x27;s interview<\/span><span class=\"meta\">Side stories · p.72–74<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#souya\">Sōya<\/a><\/span><\/h3><p class=\"setup\">Arrives for the research-lab interview in a lab coat.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Sōya<\/b> &quot;&#x27;Thank you very much, Ayanokouji-san. I never thought a stray researcher like me would be approached by such a great person.&#x27;&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Sōya<\/b> &quot;&#x27;I couldn&#x27;t very well come naked, could I?&#x27;&quot;<span class=\"pg\">p.72<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Sōya<\/b> &quot;&#x27;Isn&#x27;t that a trivial matter? My formal attire is a lab coat, so I see no problem. I&#x27;d rather you see it as a sign of my seriousness.&#x27;&quot;<span class=\"pg\">p.73<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I can generally understand people just by looking at them. That hasn&#x27;t changed even now.&#x27;&quot;<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Regret? I&#x27;m not regretting anything. Even now, when I think about why those around me betrayed me, it just makes me furious.&#x27;&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Thank you very much. I will definitely meet your expectations.&#x27;&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eccentric, unrepentant and gifted — wears a lab coat as &quot;formal attire,&quot; prides himself on reading people, bears no regret for his past crimes, and is hired on the spot.<span class=\"pg\">p.72–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is interviewed and hired by him to manage and grow the White Room subjects.<span class=\"pg\">p.72–74<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> His lab coat and attitude prompt Kamogawa&#x27;s worried questions.<span class=\"pg\">p.72–73<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p76-1","v":"y0","y":0,"o":36,"k":"narration","w":"tsukishiro naoe-sensei ayanokouji-atsuomi","q":"ayanokoji atsuomi tsukishiro  the journalist s body and the background check finds tsukishiro s business card on the floor after the interviews  arranges to meet him   then we ll get things started now  i won t let you say it s impossible   you bastard   that isn t it  huh  you re probably just keeping an eye on a politician to replace me   i don t care about that  what i want to know is whether you were impersonating naoe sensei when this journalist met you at the restaurant   at least i wouldn t be foolish enough to allow the body to be found   there are many things i dislike about this  but you can t make an omelet without breaking eggs    corpus reads  you can t make an omelet   i understand  how much   it was a dugout shed used to store agricultural tools managed by the neighborhood adults  realizes the journalist s body was intentionally left found   to chill the  rats  watching naoe  with an unknown scapegoat set to take the blame  unfazed by a possible killer   feels anger rather than fear  reads tsukishiro s strategy  and agrees to work with him while calmly disclosing his deprived childhood  meets him  recognizes him as naoe s observer cleanup man and supporter  and decides to use him to recruit personnel  realizes naoe had tsukishiro watching insuring the project from the start","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p76-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p76-1\">Tsukishiro: the journalist&#x27;s body and the background check<\/a><\/span><span class=\"meta\">Side stories · p.76–84<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Finds Tsukishiro&#x27;s business card on the floor after the interviews; arranges to meet him.<\/p><p class=\"with\">with <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;Then we&#x27;ll get things started now. I won&#x27;t let you say it&#x27;s impossible.&#x27;&quot;<span class=\"pg\">p.78<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;…You bastard.&#x27;&quot;<span class=\"pg\">p.78<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;&#x27;That isn&#x27;t it, huh? You&#x27;re probably just keeping an eye on a politician to replace me.&#x27;&quot;<span class=\"pg\">p.80<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I don&#x27;t care about that. What I want to know is whether you were impersonating Naoe-sensei when this journalist met you at the restaurant.&#x27;&quot;<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;At least I wouldn&#x27;t be foolish enough to allow the body to be found.&#x27;&quot;<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;There are many things I dislike about this, but you can&#x27;t make an omelet without breaking eggs.&#x27;&quot; — corpus reads &quot;you can&#x27;t make an omelet&quot;<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;I understand. How much?&#x27;&quot;<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;It was a dugout shed used to store agricultural tools managed by the neighborhood adults.&#x27;&quot;<span class=\"pg\">p.84<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Realizes the journalist&#x27;s body was intentionally left found — to chill the &quot;rats&quot; watching Naoe, with an unknown scapegoat set to take the blame.<span class=\"pg\">p.81–82<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Unfazed by a possible killer — feels anger rather than fear, reads Tsukishiro&#x27;s strategy, and agrees to work with him while calmly disclosing his deprived childhood.<span class=\"pg\">p.78–84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Meets him; recognizes him as Naoe&#x27;s observer/cleanup man and supporter, and decides to use him to recruit personnel.<span class=\"pg\">p.76–84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Realizes Naoe had Tsukishiro watching/insuring the project from the start.<span class=\"pg\">p.79–82<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p72-1\">← Before: Hiring Souya and the other &quot;problem&quot; experts<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p96-1\">→ After: The drive to the facility; three years of the White Room<\/button><\/div><\/article>"},{"i":"sc-tsukishiro-y0-p78-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka naoe-sensei tsukishiro","q":"tsukishiro tsukishiro s meeting  observer  cleanup man  negotiator arrives at atsuomi s office in a black bmw  having driven himself   i usually work alone  besides  i don t like entrusting someone else to drive me  it s like putting your life in their hands   yes  it s about the human resource development project  isn t it   maybe so  or maybe not   well done  you re half right  ayanokouji san   yes  i have two roles  one of the roles is just as you ve mentioned  the other is to assist the politician entrusted with the human resource development project   you ask very direct questions  ayanokouji san  and what if i said yes   that s the correct answer  you should think about things without letting your personal feelings get in the way   don t worry  i know some capable individuals who will satisfy you  ayanokouji san   however  whether i introduce them to you is another matter  you understand  right   it s important  eerie  confident and transactional   never drops his faint smile  works alone  admits nothing about the journalist  and treats personnel introductions as a business deal  meets him as naoe s observer assistant  negotiates to supply personnel  works for him as a watcher and  strong supporter   cleanup  on the project  the journalist s body was left to be found intentionally  to chill those watching naoe   tsukishiro s handiwork is implied but never admitted","h":"<article class=\"card\" id=\"sc-tsukishiro-y0-p78-1\"><h3><span class=\"ttl\"><a href=\"../../../people/tsukishiro.html#sc-tsukishiro-y0-p78-1\">Tsukishiro&#x27;s meeting: observer, cleanup man, negotiator<\/a><\/span><span class=\"meta\">Side stories · p.78–84<\/span><span class=\"by\">notes on <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/span><\/h3><p class=\"setup\">Arrives at Atsuomi&#x27;s office in a black BMW, having driven himself.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Tsukishiro<\/b> &quot;&#x27;I usually work alone. Besides, I don&#x27;t like entrusting someone else to drive me. It&#x27;s like putting your life in their hands.&#x27;&quot;<span class=\"pg\">p.79<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Tsukishiro<\/b> &quot;&#x27;Yes. It&#x27;s about the Human Resource Development Project, isn&#x27;t it?&#x27;&quot;<span class=\"pg\">p.79<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Tsukishiro<\/b> &quot;&#x27;Maybe so, or maybe not.&#x27;&quot;<span class=\"pg\">p.80<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Well done. You&#x27;re half right, Ayanokouji-san.&#x27;&quot;<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Yes. I have two roles. One of the roles is just as you&#x27;ve mentioned. The other is to assist the politician entrusted with the Human Resource Development Project.&#x27;&quot;<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;You ask very direct questions, Ayanokouji-san. And what if I said yes?&#x27;&quot;<span class=\"pg\">p.80<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;That&#x27;s the correct answer. You should think about things without letting your personal feelings get in the way.&#x27;&quot;<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;Don&#x27;t worry. I know some capable individuals who will satisfy you, Ayanokouji-san.&#x27;&quot;<span class=\"pg\">p.82<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;However, whether I introduce them to you is another matter. You understand, right?&#x27;&quot;<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;&#x27;It&#x27;s important.&#x27;&quot;<span class=\"pg\">p.83<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eerie, confident and transactional — never drops his faint smile, works alone, admits nothing about the journalist, and treats personnel introductions as a business deal.<span class=\"pg\">p.79–84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Meets him as Naoe&#x27;s observer/assistant; negotiates to supply personnel.<span class=\"pg\">p.78–84<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> Works for him as a watcher and &quot;strong supporter&quot; (cleanup) on the project.<span class=\"pg\">p.79–82<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The journalist&#x27;s body was left to be found intentionally, to chill those watching Naoe — Tsukishiro&#x27;s handiwork is implied but never admitted.<span class=\"pg\">p.80–82<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsukishiro-y0-p38-1\">← Before: The introduction: &quot;Tsukishiro Tokinari&quot;<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p96-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-atsuomi","q":"ayanokoji atsuomi the drive to the facility  three years of the white room dozes in the back seat of a car on rough mountain roads  heading to the white room three years after the project began  the car has genuine leather seats  deep and soft   far more luxurious  than his old used kei car  his dream recalls the used kei car he bought as a teen   over a hundred thousand kilometers on it  interior barely maintained   a clunker  yet he felt like head of a household driving it  he made no friends or lovers then  time alone with the car was irreplaceable  the urban scenery gave way to rough roads surrounded by mountains  the driver warns it will be bumpy   three years had passed since naoe sensei entrusted me with the human resource development project  the project  officially named the white room project  began in secrecy  financiers grew daily and funds were in surplus  the white room became a status symbol known only to those in the know  illegitimate children placed by mistresses to erase them publicly exceeded 30  of the second batch of children  he views the children overwhelmingly as experimental subjects  not charges  keeps distance from the political world and wears  both the masks of a politician and a financier","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p96-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p96-1\">The drive to the facility; three years of the White Room<\/a><\/span><span class=\"meta\">Side stories · p.96–100<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Dozes in the back seat of a car on rough mountain roads, heading to the White Room three years after the project began.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Three years had passed since Naoe-sensei entrusted me with the Human Resource Development Project.&quot;<span class=\"pg\">p.96<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The car has genuine leather seats, deep and soft, &quot;far more luxurious&quot; than his old used kei car.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> His dream recalls the used kei car he bought as a teen — over a hundred thousand kilometers on it, interior barely maintained, &quot;a clunker,&quot; yet he felt like head of a household driving it.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He made no friends or lovers then; time alone with the car was irreplaceable.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The urban scenery gave way to rough roads surrounded by mountains; the driver warns it will be bumpy.<span class=\"pg\">p.96<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The project, officially named the White Room Project, began in secrecy; financiers grew daily and funds were in surplus; the White Room became a status symbol known only to those in the know.<span class=\"pg\">p.97<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Illegitimate children placed by mistresses to erase them publicly exceeded 30% of the second batch of children.<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He views the children overwhelmingly as experimental subjects, not charges; keeps distance from the political world and wears &quot;both the masks of a politician and a financier.&quot;<span class=\"pg\">p.96–100<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p76-1\">← Before: Tsukishiro: the journalist&#x27;s body and the background check<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p101-1\">→ After: Showing Sakayanagi the lab; the exam setup<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p101-1","v":"y0","y":0,"o":36,"k":"spoken","w":"sakayanagi-narimori ayanokouji-atsuomi","q":"ayanokoji atsuomi showing sakayanagi the lab  the exam setup greets sakayanagi at the guest room   he had been standing looking out the window rather than sitting on the sofa   sorry to keep you waiting   it can t be helped  we can t make this public right now  there are countless people desperately searching for scandals involving me and naoe sensei   you were the one who helped with the white room project the most  i wanted to show it to you first   no  for these three years  i ve basically been hands off  i ve just continued to provide the necessary support for them without meddling in their plans  sakayanagi is surprised by the security  which  doesn t seem to fit this place  finds meeting the agenda free sakayanagi a  relief rather than a pain  notes he is  incorrigibly good  and could become an enemy if he learns the children s futures aren t guaranteed  guides him through the facility and seeks his assessment  values his support but distrusts his idealism","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p101-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p101-1\">Showing Sakayanagi the lab; the exam setup<\/a><\/span><span class=\"meta\">Side stories · p.101–103<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Greets Sakayanagi at the guest room — he had been standing looking out the window rather than sitting on the sofa.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Sorry to keep you waiting.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;It can&#x27;t be helped. We can&#x27;t make this public right now. There are countless people desperately searching for scandals involving me and Naoe-sensei.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;You were the one who helped with the White Room project the most. I wanted to show it to you first.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;No. For these three years, I&#x27;ve basically been hands-off. I&#x27;ve just continued to provide the necessary support for them without meddling in their plans.&quot;<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Sakayanagi is surprised by the security, which &quot;doesn&#x27;t seem to fit this place.&quot;<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Finds meeting the agenda-free Sakayanagi a &quot;relief rather than a pain&quot;; notes he is &quot;incorrigibly good&quot; and could become an enemy if he learns the children&#x27;s futures aren&#x27;t guaranteed.<span class=\"pg\">p.101–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> Guides him through the facility and seeks his assessment; values his support but distrusts his idealism.<span class=\"pg\">p.101–111<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p96-1\">← Before: The drive to the facility; three years of the White Room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p104-1\">→ After: Watching the exam: the one-way mirror and the three groups<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-narimori-y0-p101-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-narimori","q":"sakayanagi narimori sakayanagi s assessment and objection arrives early at the white room and stands looking out the window  eager for the unveiling   it s no problem  ayanokouji sensei  i arrived earlier than scheduled   i was looking forward to the white room s unveiling today   still  i was surprised by the security  it doesn t seem to fit this place   the children we took in are already over three years old  aren t they  time sure flies   speaking of three year olds  they can have simple conversations  right   i think it s amazing that they can do that   what kind of education would result in such inorganic children   excuse me  but that is undeniably corporal punishment  there s no meaning in abilities gained this way   the children i saw today were far removed from the average three year olds i know   emotions are essential for children  no  for humans   please provide an education full of love  considering the children first  idealistic and perceptive   praises the children s abilities but is disturbed by suzukake s emotionless results  insisting emotions are essential and urging an education  full of love  judges the three year olds superior to 90  of children worldwide but is unaware of the white room s true purpose as a self promotion tool  gives his assessment  leaves unconvinced after atsuomi deflects his concerns","h":"<article class=\"card\" id=\"sc-sakayanagi-narimori-y0-p101-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-narimori.html#sc-sakayanagi-narimori-y0-p101-1\">Sakayanagi&#x27;s assessment and objection<\/a><\/span><span class=\"meta\">Side stories · p.101–111<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/span><\/h3><p class=\"setup\">Arrives early at the White Room and stands looking out the window, eager for the unveiling.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;It&#x27;s no problem, Ayanokouji-sensei. I arrived earlier than scheduled.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;I was looking forward to the White Room&#x27;s unveiling today.&quot;<span class=\"pg\">p.101<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;Still, I was surprised by the security. It doesn&#x27;t seem to fit this place.&quot;<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;The children we took in are already over three years old, aren&#x27;t they? Time sure flies.&quot;<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Speaking of three-year-olds, they can have simple conversations, right?&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think it&#x27;s amazing that they can do that…&quot;<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;What kind of education would result in such inorganic children…&quot;<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;…Excuse me, but that is undeniably corporal punishment. There&#x27;s no meaning in abilities gained this way.&quot;<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The children I saw today were far removed from the average three-year-olds I know.&quot;<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Emotions are essential for children… no, for humans.&quot;<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Please provide an education full of love, considering the children first.&quot;<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Idealistic and perceptive — praises the children&#x27;s abilities but is disturbed by Suzukake&#x27;s emotionless results, insisting emotions are essential and urging an education &quot;full of love.&quot;<span class=\"pg\">p.101–111<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Judges the three-year-olds superior to 90% of children worldwide but is unaware of the White Room&#x27;s true purpose as a self-promotion tool.<span class=\"pg\">p.110<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Gives his assessment; leaves unconvinced after Atsuomi deflects his concerns.<span class=\"pg\">p.101–111<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-narimori-y0-p49-1\">← Before: Sakayanagi Narimori weighs Atsuomi&#x27;s proposal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-narimori-y0-p129-1\">→ After: Sakayanagi objects to the child&#x27;s fate<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p104-1","v":"y0","y":0,"o":36,"k":"","w":"suzukake-tanji ishida-yuusuke souya ayanokouji-atsuomi","q":"ayanokoji atsuomi watching the exam  the one way mirror and the three groups stands with sakayanagi watching the children take a comprehensive exam through the glass that  became a one way mirror  the children each wear a researcher s nameplate and quietly take their seats  at  begin  all the children flip their papers over and take up pens  no one stands up  three year old motor development noted  standing on one foot  walking on tiptoes  smoothly climbing stairs  the test is math   addition  subtraction  multiplication  division  problems elementary students would tackle  suzukake s group doesn t move at all   the  first sense of discomfort  real time camera tracking shows some answer incorrectly but without panic  agitation or distress  suzukake plays flashy music  ishida s and souya s children stop and look around  but suzukake s students keep solving problems without excessive reaction  physical tests follow  ishida s children craft with small hands  souya s use horizontal bars and jungle gyms  suzukake s play the piano    far from professional  but more than adults could do with a little practice  watches suzukake s emotionless  fear trained children outperform the other two groups in both academics and physical skill  his brutal  education   punishment from newborns  fear until it  truly vanishes  eliminating emotions  wins  atsuomi puts him in charge of the second generation  his orthodox group shows natural human development but lesser results  his group shows natural development  horrified by suzukake s corporal punishment yet impressed by results","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p104-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p104-1\">Watching the exam: the one-way mirror and the three groups<\/a><\/span><span class=\"meta\">Side stories · p.104–108<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Stands with Sakayanagi watching the children take a comprehensive exam through the glass that &quot;became a one-way mirror.&quot;<\/p><p class=\"with\">with <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a> · <a href=\"../../../people/index.html#ishida-yuusuke\">Ishida Yūsuke<\/a> · <a href=\"../../../people/index.html#souya\">Sōya<\/a><\/p><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The children each wear a researcher&#x27;s nameplate and quietly take their seats.<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> At &quot;Begin!&quot; all the children flip their papers over and take up pens; no one stands up.<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Three-year-old motor development noted: standing on one foot, walking on tiptoes, smoothly climbing stairs.<span class=\"pg\">p.104<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The test is math — addition, subtraction, multiplication, division; problems elementary students would tackle.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Suzukake&#x27;s group doesn&#x27;t move at all — the &quot;first sense of discomfort&quot;; real-time camera tracking shows some answer incorrectly but without panic, agitation or distress.<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Suzukake plays flashy music; Ishida&#x27;s and Souya&#x27;s children stop and look around, but Suzukake&#x27;s students keep solving problems without excessive reaction.<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Physical tests follow: Ishida&#x27;s children craft with small hands; Souya&#x27;s use horizontal bars and jungle gyms; Suzukake&#x27;s play the piano — &quot;far from professional&quot; but more than adults could do with a little practice.<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Watches Suzukake&#x27;s emotionless, fear-trained children outperform the other two groups in both academics and physical skill.<span class=\"pg\">p.104–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Suzukake Tanji<\/b> His brutal &quot;education&quot; (punishment from newborns, fear until it &quot;truly vanishes,&quot; eliminating emotions) wins; Atsuomi puts him in charge of the second generation.<span class=\"pg\">p.105–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishida Yūsuke<\/b> His orthodox group shows natural human development but lesser results.<span class=\"pg\">p.105–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sōya<\/b> His group shows natural development; horrified by Suzukake&#x27;s corporal punishment yet impressed by results.<span class=\"pg\">p.105–108<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p101-1\">← Before: Showing Sakayanagi the lab; the exam setup<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p109-1\">→ After: Sakayanagi&#x27;s objection; the decision to sacrifice himself<\/button><\/div><\/article>"},{"i":"sc-suzukake-tanji-y0-p105-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-narimori souya suzukake-tanji","q":"suzukake tanji suzukake s fear based education wins the exam conducts the exam for the children he raised  his group shows no reaction even to wrong answers   i made it my first task to instill children with a mature mind  even if they can t solve the problems  i ve made sure they approach them calmly and objectively  those who can t do this are punished without mercy   no  from newborns  and i don t want you to call it corporal punishment  souya  this is my education   education a process where they are punished in various ways  causing the children to become fearful  physical pain  mental anguish  and anything effective works  if you push fear far enough  eventually it will disappear   my education goes far beyond the ordinary person s learning abilities   i completely eliminated them  i believed that by prohibiting communication skills to develop through dialogue  it would be possible to raise the floor of human potential   i believe it s possible to create the strongest humans this way  ruthless and fearless in research   punishes from newborns  eliminates emotions entirely  and aims to  raise the floor of human potential  to create the strongest humans  his three year old children outperform the other groups   calm under wrong answers and flashy music  adept at piano  concentration  close to that of adults  is appointed leader for the second generation  atsuomi values his willingness to go  all the way  his methods draw sakayanagi s disgust  atsuomi tells him not to interfere with an outsider s opinion  clashes with him over the  corporal punishment  charge","h":"<article class=\"card\" id=\"sc-suzukake-tanji-y0-p105-1\"><h3><span class=\"ttl\"><a href=\"../../../people/suzukake-tanji.html#sc-suzukake-tanji-y0-p105-1\">Suzukake&#x27;s fear-based education wins the exam<\/a><\/span><span class=\"meta\">Side stories · p.105–109<\/span><span class=\"by\">notes on <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a><\/span><\/h3><p class=\"setup\">Conducts the exam for the children he raised; his group shows no reaction even to wrong answers.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a> · <a href=\"../../../people/index.html#souya\">Sōya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;I made it my first task to instill children with a mature mind. Even if they can&#x27;t solve the problems, I&#x27;ve made sure they approach them calmly and objectively. Those who can&#x27;t do this are punished without mercy.&quot;<span class=\"pg\">p.105<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;No, from newborns. And I don&#x27;t want you to call it corporal punishment, Souya. This is my education.&quot;<span class=\"pg\">p.105<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;Education—a process where they are punished in various ways, causing the children to become fearful. Physical pain, mental anguish, and anything effective works. If you push fear far enough, eventually it will disappear.&quot;<span class=\"pg\">p.106<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;My education goes far beyond the ordinary person&#x27;s learning abilities.&quot;<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I completely eliminated them. I believed that by prohibiting communication skills to develop through dialogue, it would be possible to raise the floor of human potential.&quot;<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I believe it&#x27;s possible to create the strongest humans this way.&quot;<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ruthless and fearless in research — punishes from newborns, eliminates emotions entirely, and aims to &quot;raise the floor of human potential&quot; to create the strongest humans.<span class=\"pg\">p.105–109<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> His three-year-old children outperform the other groups — calm under wrong answers and flashy music, adept at piano, concentration &quot;close to that of adults.&quot;<span class=\"pg\">p.104–108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is appointed leader for the second generation; Atsuomi values his willingness to go &quot;all the way.&quot;<span class=\"pg\">p.108–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> His methods draw Sakayanagi&#x27;s disgust; Atsuomi tells him not to interfere with an outsider&#x27;s opinion.<span class=\"pg\">p.106–109<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sōya<\/b> Clashes with him over the &quot;corporal punishment&quot; charge.<span class=\"pg\">p.105–106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-suzukake-tanji-y0-p126-1\">→ After: The Beta curriculum and Suzukake&#x27;s regret<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p109-1","v":"y0","y":0,"o":36,"k":"spoken","w":"mika ayanokouji-atsuomi","q":"ayanokoji atsuomi sakayanagi s objection  the decision to sacrifice himself sakayanagi turns his back and leaves the lab  displeased with suzukake s methods   what s needed are exceptional abilities a brain that can surpass japan s top universities and win at the world s prestigious schools  physical abilities beyond olympic athletes  and an indomitable spirit that doesn t flinch even against world leaders   i understand what you re trying to say  your opinion will sufficiently act as a reference   without sacrificing yourself  there was no true success  realizes his words carry no weight because the education is someone else s   he must personally enter the white room as a subject to give the project persuasive power  pragmatic and relentless   dismisses sakayanagi s idealism as naive  and resolves to sacrifice himself to make the white room  change the world  calls her in the evening with a favor   the first step of his plan","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p109-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p109-1\">Sakayanagi&#x27;s objection; the decision to sacrifice himself<\/a><\/span><span class=\"meta\">Side stories · p.109–113<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Sakayanagi turns his back and leaves the lab, displeased with Suzukake&#x27;s methods.<\/p><p class=\"with\">with <a href=\"../../../people/mika.html\">Mika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;What&#x27;s needed are exceptional abilities—a brain that can surpass Japan&#x27;s top universities and win at the world&#x27;s prestigious schools, physical abilities beyond Olympic athletes, and an indomitable spirit that doesn&#x27;t flinch even…<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I understand what you&#x27;re trying to say. Your opinion will sufficiently act as a reference.&quot;<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Without sacrificing yourself, there was no true success.&quot;<span class=\"pg\">p.112<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;What&#x27;s needed are exceptional abilities—a brain that can surpass Japan&#x27;s top universities and win at the world&#x27;s prestigious schools, physical abilities beyond Olympic athletes, and an indomitable spirit that doesn&#x27;t flinch even against world leaders.&quot;<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Realizes his words carry no weight because the education is someone else&#x27;s — he must personally enter the White Room as a subject to give the project persuasive power.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Pragmatic and relentless — dismisses Sakayanagi&#x27;s idealism as naive, and resolves to sacrifice himself to make the White Room &quot;change the world.&quot;<span class=\"pg\">p.109–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mika<\/b> Calls her in the evening with a favor — the first step of his plan.<span class=\"pg\">p.113<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p104-1\">← Before: Watching the exam: the one-way mirror and the three groups<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p117-1\">→ After: Paying Mika; the naming of Kiyotaka<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p117-1","v":"y0","y":0,"o":36,"k":"spoken","w":"mika ayanokouji-kiyotaka tsukishiro ayanokouji-atsuomi","q":"ayanokoji atsuomi paying mika  the naming of kiyotaka meets mika in a room with bundles of bills arranged on a white table   fifty million yen in cash  no trace  the fifty million is the amount after deducting all childbirth and hospitalization expenses  mika is dressed in a suit she  probably wasn t used to wearing  a normal surrogacy would cost nearly half this at the high end   he pays more than double the market rate   money is heavy  but i can prepare as much as necessary to live  that s what the world s like on this side   i hardly remember ever doing so  well  maybe i ll pay them when i start a new job  so it s fine   no matter what  you will never be recognized as the mother in the future   that s none of your business  once the contract is finalized  our connection ends   you would do anything for money and yourself  that s the highest praise i can give you   names are just symbols  no matter who assigns them  a person s essence doesn t change   that suggestion is very like you  adds three million yen as a  celebration gift severance  hands her a pre filled divorce form  eleven days since the birth  three days left before registration  mika names the child  kiyotaka    after the host she is seeing  atsuomi writes  kiyotaka  in the register after she leaves  utterly cold and transactional   feels no attachment  offers his own child as a  cheap purchase  so long as he is useful for five years  and keeps mika as legal mother only to protect credibility  pays her for the surrogacy  severs all rights  and keeps her as a nominal wife  she names the child kiyotaka  his newborn son  named kiyotaka by mika  registered by atsuomi and destined to enter the white room as a fourth generation subject  waits in the next room  discusses disposing of mika","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p117-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p117-1\">Paying Mika; the naming of Kiyotaka<\/a><\/span><span class=\"meta\">Side stories · p.117–122<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Meets Mika in a room with bundles of bills arranged on a white table — fifty million yen in cash, no trace.<\/p><p class=\"with\">with <a href=\"../../../people/mika.html\">Mika<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Money is heavy, but I can prepare as much as necessary to live. That&#x27;s what the world&#x27;s like on this side.&quot;<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I hardly remember ever doing so. Well, maybe I&#x27;ll pay them when I start a new job, so it&#x27;s fine.&quot;<span class=\"pg\">p.118<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;No matter what, you will never be recognized as the mother in the future.&quot;<span class=\"pg\">p.118<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The fifty million is the amount after deducting all childbirth and hospitalization expenses; Mika is dressed in a suit she &quot;probably wasn&#x27;t used to wearing.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> A normal surrogacy would cost nearly half this at the high end — he pays more than double the market rate.<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s none of your business. Once the contract is finalized, our connection ends.&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You would do anything for money and yourself. That&#x27;s the highest praise I can give you.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Names are just symbols. No matter who assigns them, a person&#x27;s essence doesn&#x27;t change.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That suggestion is very like you.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Adds three million yen as a &quot;celebration gift&quot;/severance; hands her a pre-filled divorce form; eleven days since the birth, three days left before registration.<span class=\"pg\">p.121–122<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Mika names the child &quot;Kiyotaka&quot; — after the host she is seeing. Atsuomi writes &quot;Kiyotaka&quot; in the register after she leaves.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Utterly cold and transactional — feels no attachment, offers his own child as a &quot;cheap purchase&quot; so long as he is useful for five years, and keeps Mika as legal mother only to protect credibility.<span class=\"pg\">p.117–123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mika<\/b> Pays her for the surrogacy, severs all rights, and keeps her as a nominal wife; she names the child Kiyotaka.<span class=\"pg\">p.117–123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His newborn son, named Kiyotaka by Mika; registered by Atsuomi and destined to enter the White Room as a fourth-generation subject.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Waits in the next room; discusses disposing of Mika.<span class=\"pg\">p.123<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p109-1\">← Before: Sakayanagi&#x27;s objection; the decision to sacrifice himself<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p124-1\">→ After: The Beta curriculum decision; 74 samples<\/button><\/div><\/article>"},{"i":"sc-mika-y0-p117-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-atsuomi ayanokouji-kiyotaka mika","q":"mika mika s surrogacy contract and the naming sits across from atsuomi in a suit she isn t used to  looking at fifty million yen in cash on a white table   there s fifty million  i ve prepared it in cash as you wished  there s no trace   politicians really have control over money and everything else  don t they  it must have been easy for you to prepare fifty million   money is heavy  but i can prepare as much as necessary to live  that s what the world s like on this side   so  the fact that your own child was born doesn t affect your heart at all  does it   of course not  if that were the case  i wouldn t hand over the child  for me  the whole process of carrying and giving birth to that child was just a job  nothing more  nothing less   well  whether it was worth the job is another matter  i started to regret it when my stomach got bigger and the morning sickness got worse   it seems so  to save fifty million  you need to earn about a hundred million  right   have you ever properly paid taxes   atsuomi  did you ever think you loved me  even once   then  kiyotaka  name him kiyotaka   you re really always so calm  with such a cold heart   goodbye  atsuomi  the time i spent with you has been a valuable experience for me  for better or worse  mercenary and self aware   carried the child purely for money  names him after the host she is seeing  and values money and herself most   the highest praise  atsuomi can give her  earns over a million a month in her line of work  hardly remembers paying taxes  touched the stack of bills and smiled  had a paternal test in mind   atsuomi anticipated it  so he could not be surprised by the child s parentage  names him kiyotaka  after her host  so the name will stay in her memory  surrogacy arrangement  no lingering feelings on either side","h":"<article class=\"card\" id=\"sc-mika-y0-p117-1\"><h3><span class=\"ttl\"><a href=\"../../../people/mika.html#sc-mika-y0-p117-1\">Mika&#x27;s surrogacy contract and the naming<\/a><\/span><span class=\"meta\">Side stories · p.117–122<\/span><span class=\"by\">notes on <a href=\"../../../people/mika.html\">Mika<\/a><\/span><\/h3><p class=\"setup\">Sits across from Atsuomi in a suit she isn&#x27;t used to, looking at fifty million yen in cash on a white table.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;There&#x27;s fifty million. I&#x27;ve prepared it in cash as you wished. There&#x27;s no trace.&quot;<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Mika<\/b> &quot;Politicians really have control over money and everything else, don&#x27;t they? It must have been easy for you to prepare fifty million.&quot;<span class=\"pg\">p.117<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Money is heavy, but I can prepare as much as necessary to live. That&#x27;s what the world&#x27;s like on this side.&quot;<span class=\"pg\">p.117<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;So, the fact that your own child was born doesn&#x27;t affect your heart at all, does it?&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Of course not. If that were the case, I wouldn&#x27;t hand over the child. For me, the whole process of carrying and giving birth to that child was just a job, nothing more, nothing less.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Well, whether it was worth the job is another matter. I started to regret it when my stomach got bigger and the morning sickness got worse.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It seems so. To save fifty million, you need to earn about a hundred million, right?&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Have you ever properly paid taxes?&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Atsuomi, did you ever think you loved me, even once?&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Then… Kiyotaka. Name him Kiyotaka.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You&#x27;re really always so calm, with such a cold heart.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Goodbye, Atsuomi. The time I spent with you has been a valuable experience for me, for better or worse.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Mercenary and self-aware — carried the child purely for money, names him after the host she is seeing, and values money and herself most; &quot;the highest praise&quot; Atsuomi can give her.<span class=\"pg\">p.117–122<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Earns over a million a month in her line of work; hardly remembers paying taxes; touched the stack of bills and smiled.<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Had a paternal test in mind — Atsuomi anticipated it, so he could not be surprised by the child&#x27;s parentage.<span class=\"pg\">p.119<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Names him Kiyotaka, after her host, so the name will stay in her memory.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Surrogacy arrangement; no lingering feelings on either side.<span class=\"pg\">p.117–123<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p124-1","v":"y0","y":0,"o":36,"k":"spoken","w":"suzukake-tanji tabuchi ishida-yuusuke ayanokouji-atsuomi","q":"ayanokoji atsuomi the beta curriculum decision  74 samples on the day kiyotaka arrives  gathers the researchers  tabuchi  with dark circles under his eyes  projects the curriculum onto a large screen  dropout rates  first generation 14  at age five  second 6  at age two  predicted  20  by five  third 6  at age one  predicted  25  ability increase between first and third generations  11 37  dropouts  problem  extremely low social adaptability   99  lived only in the white room  first generation knows the outside only through fragmented materials photos and can t imagine a cityscape  no real experience with vending machines  streetlights  shopping streets  convenience stores or supermarkets   adopt the beta curriculum   i said to adopt the beta curriculum  don t make me repeat myself   i will provide the strictest education to my own child  it s an excellent opportunity   frankly  i wouldn t mind if it kills them   i ve mostly picked up those who are disposable   we ll proceed as planned  send them to the facility we prepared and let them fend for themselves   just follow the orders  if you defy my commands  i won t hesitate to cut you off  even if it s you  kept the list of wealthy family children secret from researchers so they receive no special treatment  used the ooba group and dark brokers to acquire  disposable  samples  relentlessly experimental   applies the  unreachable  beta curriculum to his own son  assembles 74 samples  double the third generation  and crushes tabuchi s objections  orders him to adopt beta  suzukake regrets creating it but accepts  presents the data  resists and is told to obey or be cut off  objects  is it really  all right  atsuomi holds firm","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p124-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p124-1\">The Beta curriculum decision; 74 samples<\/a><\/span><span class=\"meta\">Side stories · p.124–129<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">On the day Kiyotaka arrives, gathers the researchers; Tabuchi (with dark circles under his eyes) projects the curriculum onto a large screen.<\/p><p class=\"with\">with <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a> · <a href=\"../../../people/index.html#tabuchi\">Tabuchi<\/a> · <a href=\"../../../people/index.html#ishida-yuusuke\">Ishida Yūsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Adopt the Beta curriculum.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I said to adopt the Beta curriculum. Don&#x27;t make me repeat myself.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I will provide the strictest education to my own child. It&#x27;s an excellent opportunity.&quot;<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Dropout rates: first generation 14% at age five; second 6% at age two (predicted &gt;20% by five); third 6% at age one (predicted &gt;25%). Ability increase between first and third generations: 11–37%.<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Dropouts&#x27; problem: extremely low social adaptability — 99% lived only in the White Room; first generation knows the outside only through fragmented materials/photos and can&#x27;t imagine a cityscape; no real experience with vending machines, streetlights, shopping streets, convenience stores or supermarkets.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Frankly, I wouldn&#x27;t mind if it kills them.&quot;<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve mostly picked up those who are disposable.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll proceed as planned. Send them to the facility we prepared and let them fend for themselves.&quot;<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Just follow the orders. If you defy my commands, I won&#x27;t hesitate to cut you off, even if it&#x27;s you.&quot;<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Kept the list of wealthy-family children secret from researchers so they receive no special treatment; used the Ooba group and dark brokers to acquire &quot;disposable&quot; samples.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Relentlessly experimental — applies the &quot;unreachable&quot; Beta curriculum to his own son, assembles 74 samples (double the third generation), and crushes Tabuchi&#x27;s objections.<span class=\"pg\">p.124–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Suzukake Tanji<\/b> Orders him to adopt Beta; Suzukake regrets creating it but accepts.<span class=\"pg\">p.126–128<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tabuchi<\/b> Presents the data; resists and is told to obey or be cut off.<span class=\"pg\">p.124, 128–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishida Yūsuke<\/b> Objects (&quot;Is it really… all right?&quot;); Atsuomi holds firm.<span class=\"pg\">p.127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p117-1\">← Before: Paying Mika; the naming of Kiyotaka<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p129-1\">→ After: Sakayanagi&#x27;s phone call: offering to take his child<\/button><\/div><\/article>"},{"i":"sc-suzukake-tanji-y0-p126-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-kiyotaka ishida-yuusuke suzukake-tanji","q":"suzukake tanji the beta curriculum and suzukake s regret  adopt the beta curriculum   i should ve explained it to you at the time   in practical terms  i see the fifth or sixth level as the limit of human development   ishida san  i myself  having started research with you and the others  have understood a lot  there are lines that humans shouldn t cross   i regret creating the beta curriculum so much   it s my role to feel the pain  i will thoroughly engage in the fourth generation s education  grown and reflective   regrets the  unreachable  beta curriculum and believes there are lines humans shouldn t cross  yet accepts the duty to carry it out because atsuomi ordered it  is ordered to adopt beta for the fourth generation  which includes atsuomi s son  appeals to his humanity  suzukake persuades the reluctant researchers to proceed","h":"<article class=\"card\" id=\"sc-suzukake-tanji-y0-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/suzukake-tanji.html#sc-suzukake-tanji-y0-p126-1\">The Beta curriculum and Suzukake&#x27;s regret<\/a><\/span><span class=\"meta\">Side stories · p.126–128<\/span><span class=\"by\">notes on <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#ishida-yuusuke\">Ishida Yūsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;Adopt the Beta curriculum.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;I should&#x27;ve explained it to you at the time.&quot;<span class=\"pg\">p.126<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;In practical terms, I see the fifth or sixth level as the limit of human development.&quot;<span class=\"pg\">p.126<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Ishida-san, I myself, having started research with you and the others, have understood a lot. There are lines that humans shouldn&#x27;t cross.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I regret creating the Beta curriculum so much.&quot;<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s my role to feel the pain. I will thoroughly engage in the fourth generation&#x27;s education.&quot;<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Grown and reflective — regrets the &quot;unreachable&quot; Beta curriculum and believes there are lines humans shouldn&#x27;t cross, yet accepts the duty to carry it out because Atsuomi ordered it.<span class=\"pg\">p.126–128<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is ordered to adopt Beta for the fourth generation, which includes Atsuomi&#x27;s son.<span class=\"pg\">p.126<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishida Yūsuke<\/b> Appeals to his humanity; Suzukake persuades the reluctant researchers to proceed.<span class=\"pg\">p.127–128<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-suzukake-tanji-y0-p105-1\">← Before: Suzukake&#x27;s fear-based education wins the exam<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-suzukake-tanji-y0-p242-1\">→ After: Suzukake&#x27;s recorded reflections (March 11th)<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p129-1","v":"y0","y":0,"o":36,"k":"spoken","w":"sakayanagi-narimori ayanokouji-atsuomi","q":"ayanokoji atsuomi sakayanagi s phone call  offering to take his child steps into the corridor to answer a call from sakayanagi about the newborn   i ve been prepared ever since i decided to create this white room  a person in charge of educating abandoned babies can t expect to have a proper family   i see  i knew you would say that  dismisses sakayanagi s concern that his son deserves parental love  notes sakayanagi would raise his own unborn child with love and looks forward to it as one of his achievements  calls about the birth  offers to take atsuomi s child  intends to give his own unborn child all the love he can","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p129-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p129-1\">Sakayanagi&#x27;s phone call: offering to take his child<\/a><\/span><span class=\"meta\">Side stories · p.129–130<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Steps into the corridor to answer a call from Sakayanagi about the newborn.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I&#x27;ve been prepared ever since I decided to create this White Room. A person in charge of educating abandoned babies can&#x27;t expect to have a proper family.&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I see. I knew you would say that.&quot;<span class=\"pg\">p.130<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Dismisses Sakayanagi&#x27;s concern that his son deserves parental love; notes Sakayanagi would raise his own unborn child with love and looks forward to it as one of his achievements.<span class=\"pg\">p.129–130<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> Calls about the birth; offers to take Atsuomi&#x27;s child; intends to give his own unborn child all the love he can.<span class=\"pg\">p.129–130<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p124-1\">← Before: The Beta curriculum decision; 74 samples<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p199-1\">→ After: Naoe withdraws; the White Room scrapped<\/button><\/div><\/article>"},{"i":"sc-sakayanagi-narimori-y0-p129-1","v":"y0","y":0,"o":36,"k":"spoken","w":"ayanokouji-kiyotaka ayanokouji-atsuomi sakayanagi-narimori","q":"sakayanagi narimori sakayanagi objects to the child s fate  ayanokouji sensei   i didn t want to contact you this way  but your son has been born   is it really okay  it s your long awaited son   however  that might be a bit too much of a leap   however  your son is different  he should receive the love of both a mother and a father   you might have a child soon too  if necessary  i am prepared to take in your child   i  i can t be as strong as you  sensei  i intend to give my unborn child all the love i can with my wife  compassionate and principled   argues atsuomi s son deserves parental love and offers to take him in  plans to raise his own unborn child with love  offers to take in atsuomi s newborn son  calls about the birth  cannot sway him and is rebuffed","h":"<article class=\"card\" id=\"sc-sakayanagi-narimori-y0-p129-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-narimori.html#sc-sakayanagi-narimori-y0-p129-1\">Sakayanagi objects to the child&#x27;s fate<\/a><\/span><span class=\"meta\">Side stories · p.129–130<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;Ayanokouji-sensei…&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;I didn&#x27;t want to contact you this way, but your son has been born.&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Narimori<\/b> &quot;…Is it really okay? It&#x27;s your long-awaited son.&quot;<span class=\"pg\">p.129<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;However, that might be a bit too much of a leap.&quot;<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;However, your son is different. He should receive the love of both a mother and a father.&quot;<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You might have a child soon too. If necessary, I am prepared to take in your child.&quot;<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I… I can&#x27;t be as strong as you, Sensei. I intend to give my unborn child all the love I can with my wife.&quot;<span class=\"pg\">p.130<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Compassionate and principled — argues Atsuomi&#x27;s son deserves parental love and offers to take him in; plans to raise his own unborn child with love.<span class=\"pg\">p.129–130<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Offers to take in Atsuomi&#x27;s newborn son.<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Calls about the birth; cannot sway him and is rebuffed.<span class=\"pg\">p.129–130<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sakayanagi-narimori-y0-p101-1\">← Before: Sakayanagi&#x27;s assessment and objection<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p131-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka first memory  the pure white ceiling recalls his very first memory in the white room   staring at a pure white ceiling   the first memory everyone shared was of  white  spreading across the entirety of the surface   as the name  white room  implied  this facility was based on the color white   the ceiling was no exception   in my first memory  i was staring at that pure white ceiling   before showing interest in my own fingertips  i just wondered what this white ceiling was   day after day  i just stared at the ceiling   at first  i cried  crying out of loneliness  eventually  i learned that no one would come to help  a newborn  unable to speak  accepted the environment as  the first lesson  later he became aware of his fingers  sucking and licking them to pass empty time   inhuman adults  brought only the nutrition necessary to live  even when sick  treatment was unemotional and life returned to normal   no one panicked  worried or rejoiced  learned at an early stage that joy  anger  sorrow and pleasure were  practically useless  in the facility","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p131-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p131-1\">First memory: the pure white ceiling<\/a><\/span><span class=\"meta\">Side stories · p.131<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls his very first memory in the White Room — staring at a pure white ceiling.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The first memory everyone shared was of &#x27;white&#x27; spreading across the entirety of the surface.&quot;<span class=\"pg\">p.131<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;As the name &#x27;White Room&#x27; implied, this facility was based on the color white.&quot;<span class=\"pg\">p.131<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;The ceiling was no exception.&quot;<span class=\"pg\">p.131<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;In my first memory, I was staring at that pure white ceiling.&quot;<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Before showing interest in my own fingertips, I just wondered what this white ceiling was.&quot;<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Day after day, I just stared at the ceiling.&quot;<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;At first, I cried, crying out of loneliness. Eventually, I learned that no one would come to help.&quot;<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> A newborn, unable to speak, accepted the environment as &quot;the first lesson&quot;; later he became aware of his fingers, sucking and licking them to pass empty time.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> &quot;Inhuman adults&quot; brought only the nutrition necessary to live; even when sick, treatment was unemotional and life returned to normal — no one panicked, worried or rejoiced.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Learned at an early stage that joy, anger, sorrow and pleasure were &quot;practically useless&quot; in the facility.<span class=\"pg\">p.131<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p12-1\">← Before: Born into the White Room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p132-1\">→ After: The gummy hand-game at age two; the third option<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p132-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the gummy hand game at age two  the third option recalls a one on one test at around age two   an instructor holds a tiny gummy in one hand   if you can guess where the gummy is  you can eat it   i ll keep giving you a chance to answer until you miss three times  a tiny gummy   a rare snack in the facility  with a sweetness he craved  the instructor s face was stern  almost expressionless  and so was the two year old kiyotaka s  naturally  the first four rounds the gummy is in the right hand  the fifth the instructor crosses both arms behind his back  grip and position identical  gaze unchanged   a fifty fifty choice  he touches the right  which is empty  other children had a slightly higher right hand bias with  no clear reason  all instructors actually held the gummies in their left hands that round  he observes the other children s choices   an overwhelming number point left  but the answer is right   and infers the instructor s gummy is in the right  he points right and a green gummy appears  the hands won t open until everyone has answered  you re the last one  everyone guesses wrong  and most children hit three misses and lose their chance   why point behind   gummy  it s not there  on his last chance he points behind  neither hand  reasoning the gummy might be hidden elsewhere  the instructor opens both hands   the gummy was in the right  the instructor eats it himself   behind  with a special extra chance  he again points behind  the gummy was in the left    too bad again  are you frustrated  he nods  frustrated not by wanting the gummy but by his thinking being off  the adults whisper that he   unlike the other children   observed others  choices  conceived a third option  and didn t discard it even after it was disproved  they remark it is not the thought process of a two year old  and argue over whether he understands them  even at two  reasons by observation and inference rather than instinct   tracks others  behavior  considers hidden alternatives  and is driven by accuracy rather than reward  when the buzzer ends the test  the adults leave and not a single child cries   being left alone with no help was deeply ingrained by age two","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p132-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p132-1\">The gummy hand-game at age two; the third option<\/a><\/span><span class=\"meta\">Side stories · p.132–137<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls a one-on-one test at around age two — an instructor holds a tiny gummy in one hand.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If you can guess where the gummy is, you can eat it.&quot;<span class=\"pg\">p.132<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I&#x27;ll keep giving you a chance to answer until you miss three times.&quot;<span class=\"pg\">p.132<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Why point behind?&quot;<span class=\"pg\">p.135<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> A tiny gummy — a rare snack in the facility, with a sweetness he craved; the instructor&#x27;s face was stern, almost expressionless, and so was the two-year-old Kiyotaka&#x27;s, naturally.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The first four rounds the gummy is in the right hand; the fifth the instructor crosses both arms behind his back, grip and position identical, gaze unchanged — a fifty-fifty choice; he touches the right, which is empty.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Other children had a slightly higher right-hand bias with &quot;no clear reason&quot;; all instructors actually held the gummies in their left hands that round.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He observes the other children&#x27;s choices — an overwhelming number point left, but the answer is right — and infers the instructor&#x27;s gummy is in the right; he points right and a green gummy appears.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The hands won&#x27;t open until everyone has answered (&quot;You&#x27;re the last one&quot;); everyone guesses wrong, and most children hit three misses and lose their chance.<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Gummy, it&#x27;s not there.&quot;<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> On his last chance he points behind (neither hand), reasoning the gummy might be hidden elsewhere; the instructor opens both hands — the gummy was in the right; the instructor eats it himself.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Behind.&quot;<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> With a special extra chance, he again points behind; the gummy was in the left — &quot;Too bad again. Are you frustrated?&quot; He nods, frustrated not by wanting the gummy but by his thinking being off.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The adults whisper that he — unlike the other children — observed others&#x27; choices, conceived a third option, and didn&#x27;t discard it even after it was disproved; they remark it is not the thought process of a two-year-old, and argue over whether he understands them.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Even at two, reasons by observation and inference rather than instinct — tracks others&#x27; behavior, considers hidden alternatives, and is driven by accuracy rather than reward.<span class=\"pg\">p.132–137<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> When the buzzer ends the test, the adults leave and not a single child cries — being left alone with no help was deeply ingrained by age two.<span class=\"pg\">p.137<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p131-1\">← Before: First memory: the pure white ceiling<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p138-1\">→ After: Names, no surnames; the written exam at four<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p138-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka names  no surnames  the written exam at four recalls being told to state his name    kiyotaka    a symbol  an identifying sequence of letters   kiyotaka  white room children were taught names to identify people  but not surnames when young   instructors used first names  a rule set to prevent future identification  by age four  new curriculums were implemented one after another  the written exam used hiragana  katakana  the alphabet  numbers and simple kanji  with pen gripping fingers moving without hesitation  a certain score within a time limit was required or there was a penalty  elegant handwriting was mandatory   no extra points for good handwriting  but hurried or poor handwriting meant deductions   no one in this facility asked whether the problems could be solved or not  the only answer was that everyone could do it  those who couldn t were eliminated at age three  the fourth generation initially numbered seventy four  those judged incapable at three had already dropped out  the written exam lasted thirty minutes but strong students finished in half to two thirds the time","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p138-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p138-1\">Names, no surnames; the written exam at four<\/a><\/span><span class=\"meta\">Side stories · p.138–139<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls being told to state his name — &quot;Kiyotaka&quot; — a symbol, an identifying sequence of letters.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Kiyotaka.&quot;<span class=\"pg\">p.138<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> White Room children were taught names to identify people, but not surnames when young — instructors used first names, a rule set to prevent future identification.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> By age four, new curriculums were implemented one after another; the written exam used hiragana, katakana, the alphabet, numbers and simple kanji, with pen-gripping fingers moving without hesitation.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> A certain score within a time limit was required or there was a penalty; elegant handwriting was mandatory — no extra points for good handwriting, but hurried or poor handwriting meant deductions.<span class=\"pg\">p.138–139<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> &quot;No one in this facility asked whether the problems could be solved or not. The only answer was that everyone could do it&quot;; those who couldn&#x27;t were eliminated at age three.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Numbers<\/span> The fourth generation initially numbered seventy-four; those judged incapable at three had already dropped out. The written exam lasted thirty minutes but strong students finished in half to two-thirds the time.<span class=\"pg\">p.139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p132-1\">← Before: The gummy hand-game at age two; the third option<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p140-1\">→ After: Judo, randori, and Mikuru&#x27;s collapse<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p140-1","v":"y0","y":0,"o":36,"k":"","w":"mikuru shiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka judo  randori  and mikuru s collapse recalls the judo curriculum added in their fourth year   being slammed to the floor by instructors  breathing knocked out  forced to stand  the instructor shouts for them to get up  that he doesn t spare even children  and that no one will cry for them   the translation leaves these lines untagged  so no  says  row is claimed for them  judo had been learned for four months  progressing to randori  one on one sparring  the children were always made to taste bitter defeat against instructors  mikuru  pleading  i can t  stand anymore  clung to the instructor s leg  was shaken off  kicked away  spinning across the floor while scattering vomit around her  and lost consciousness  the instructor called her a  weakling  and had her removed  the instructors were  the kind who wouldn t hesitate to push women and children to the brink of death  being thrown  breathing difficulty and sobbing pain were normal  and even thinking about them a waste of energy  after harsh lessons  they did randori with three other children at day s end  weak prey was hunted by the strong   a lesson learned  his record  144 fights  127 wins  17 losses  currently a four win streak  witnesses her brutal breakdown and removal  faces him in randori   shiro s record 135 wins  9 losses  best at judo  waited and aimed for a counter this third fight","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p140-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p140-1\">Judo, randori, and Mikuru&#x27;s collapse<\/a><\/span><span class=\"meta\">Side stories · p.140–142<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls the judo curriculum added in their fourth year — being slammed to the floor by instructors, breathing knocked out, forced to stand.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#mikuru\">Mikuru<\/a> · <a href=\"../../../people/index.html#shiro\">Shiro<\/a><\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The instructor shouts for them to get up, that he doesn&#x27;t spare even children, and that no one will cry for them — the translation leaves these lines untagged, so no `[says]` row is claimed for them.<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Judo had been learned for four months, progressing to randori (one-on-one sparring); the children were always made to taste bitter defeat against instructors.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Mikuru, pleading &quot;I can&#x27;t… stand anymore…!&quot;, clung to the instructor&#x27;s leg, was shaken off, kicked away &quot;spinning across the floor while scattering vomit around her,&quot; and lost consciousness; the instructor called her a &quot;weakling&quot; and had her removed.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The instructors were &quot;the kind who wouldn&#x27;t hesitate to push women and children to the brink of death&quot;; being thrown, breathing difficulty and sobbing pain were normal, and even thinking about them a waste of energy.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> After harsh lessons, they did randori with three other children at day&#x27;s end; weak prey was hunted by the strong — a lesson learned. His record: 144 fights, 127 wins, 17 losses, currently a four-win streak.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mikuru<\/b> Witnesses her brutal breakdown and removal.<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiro<\/b> Faces him in randori — Shiro&#x27;s record 135 wins, 9 losses, best at judo; waited and aimed for a counter this third fight.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p138-1\">← Before: Names, no surnames; the written exam at four<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p144-1\">→ After: Yuki, carrots, and the first smile<\/button><\/div><\/article>"},{"i":"sc-mikuru-y0-p140-1","v":"y0","y":0,"o":36,"k":"narration","w":"mikuru","q":"mikuru mikuru breaks under the judo instructor breaks down during judo randori against an instructor   i can t  stand anymore  the first child to visibly break   pleads for mercy  clings to the instructor s leg  is kicked away vomiting and loses consciousness  called a  weakling  and dragged out  the instructor s kicking  wasn t serious  but clearly stronger than usual  mikuru s excessive reaction is described as something that would decrease day by day until even expressions of pain faded","h":"<article class=\"card\" id=\"sc-mikuru-y0-p140-1\"><h3><span class=\"ttl\">Mikuru breaks under the judo instructor<\/span><span class=\"meta\">Side stories · p.140–141<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#mikuru\">Mikuru<\/a><\/span><\/h3><p class=\"setup\">Breaks down during judo randori against an instructor.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Mikuru<\/b> &quot;I can&#x27;t… stand anymore…!&quot;<span class=\"pg\">p.140<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The first child to visibly break — pleads for mercy, clings to the instructor&#x27;s leg, is kicked away vomiting and loses consciousness; called a &quot;weakling&quot; and dragged out.<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The instructor&#x27;s kicking &quot;wasn&#x27;t serious&quot; but clearly stronger than usual; Mikuru&#x27;s excessive reaction is described as something that would decrease day by day until even expressions of pain faded.<span class=\"pg\">p.141<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shiro-y0-p142-1","v":"y0","y":0,"o":36,"k":"","w":"ayanokouji-kiyotaka shiro","q":"shiro shiro  the best judoka  waits for a counter faces kiyotaka in randori  quietly waiting for the signal  the best at judo among the children   record 135 wins  9 losses  usually aggressive and taking the initiative  but this third fight against kiyotaka he waits and aims for a counter  a formidable rival  they have fought twice before  each winning once","h":"<article class=\"card\" id=\"sc-shiro-y0-p142-1\"><h3><span class=\"ttl\">Shiro, the best judoka, waits for a counter<\/span><span class=\"meta\">Side stories · p.142<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#shiro\">Shiro<\/a><\/span><\/h3><p class=\"setup\">Faces Kiyotaka in randori, quietly waiting for the signal.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The best at judo among the children — record 135 wins, 9 losses; usually aggressive and taking the initiative, but this third fight against Kiyotaka he waits and aims for a counter.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> A formidable rival; they have fought twice before, each winning once.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p144-1","v":"y0","y":0,"o":36,"k":"narration","w":"yuki shiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka yuki  carrots  and the first smile recalls dinner at age five  when the children had never directly spoken to one another  the number of children had dropped to about fifty by age five  no one paid attention    there was no room to care  the children never talked  no favoritism in food  no sense of comradeship  their presence was  no different from the surrounding scenery   i don t like it   kiyotaka  do you like it   i don t like them either  he analyzed carrots   beta carotene   vitamin a  cell aging  skin and mucous membranes  immunity   but had never considered liking or disliking them  concluded he didn t dislike them  checked the surveillance camera  the instructors monitored meals and audio  and since there was no scolding  such conversation was apparently allowed  though never encouraged  yuki walked three laps around the small room  then tripped before him  he caught her and noted  it s strange to trip over nothing  then considered accumulated fatigue and dismissed it  she made an expression he had never seen   the orbicularis oculi around the eyes and corrugator supercilii near the eyebrows   which she realized was a  smile  something humans have from birth as instinct  never taught in the white room  the girl who always sat in front of him  her carrot question and unlearned smile are his first encounters with spontaneous emotion  sits on his left and answers yuki s question for him","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p144-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p144-1\">Yuki, carrots, and the first smile<\/a><\/span><span class=\"meta\">Side stories · p.144–148<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls dinner at age five, when the children had never directly spoken to one another.<\/p><p class=\"with\">with <a href=\"../../../people/yuki.html\">Yuki<\/a> · <a href=\"../../../people/index.html#shiro\">Shiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;I don&#x27;t like it…&quot;<span class=\"pg\">p.144<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;Kiyotaka, do you like it?&quot;<span class=\"pg\">p.145<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Shiro<\/b> &quot;I don&#x27;t like them either.&quot;<span class=\"pg\">p.145<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The number of children had dropped to about fifty by age five; no one paid attention — &quot;there was no room to care.&quot;<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The children never talked: no favoritism in food, no sense of comradeship; their presence was &quot;no different from the surrounding scenery.&quot;<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He analyzed carrots — beta-carotene → Vitamin A, cell aging, skin and mucous membranes, immunity — but had never considered liking or disliking them; concluded he didn&#x27;t dislike them.<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Checked the surveillance camera; the instructors monitored meals and audio, and since there was no scolding, such conversation was apparently allowed, though never encouraged.<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Yuki walked three laps around the small room, then tripped before him; he caught her and noted &quot;It&#x27;s strange to trip over nothing,&quot; then considered accumulated fatigue and dismissed it.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> She made an expression he had never seen — the orbicularis oculi around the eyes and corrugator supercilii near the eyebrows — which she realized was a &quot;smile,&quot; something humans have from birth as instinct, never taught in the White Room.<span class=\"pg\">p.146–148<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yuki<\/b> The girl who always sat in front of him; her carrot question and unlearned smile are his first encounters with spontaneous emotion.<span class=\"pg\">p.144–148<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiro<\/b> Sits on his left and answers Yuki&#x27;s question for him.<span class=\"pg\">p.145<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p140-1\">← Before: Judo, randori, and Mikuru&#x27;s collapse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p149-1\">→ After: The daily schedule at age five<\/button><\/div><\/article>"},{"i":"sc-yuki-y0-p144-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka shiro yuki","q":"yuki yuki s carrot question and the first smile sits in front of kiyotaka at dinner and  in a first  speaks to another child   i don t like it   kiyotaka  do you like it   yeah  i m not tired  but i somehow tripped  it s a bit strange  isn t it  the first child to initiate conversation and to display a spontaneous emotion   after tripping and being caught by kiyotaka  she makes a  smile  an expression never taught in the white room but instinctive to humans  sits in front of him  asks if he likes carrots and trips before him  prompting his analysis of her unfamiliar expression  her carrot question is answered by shiro instead of kiyotaka","h":"<article class=\"card\" id=\"sc-yuki-y0-p144-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yuki.html#sc-yuki-y0-p144-1\">Yuki&#x27;s carrot question and the first smile<\/a><\/span><span class=\"meta\">Side stories · p.144–148<\/span><span class=\"by\">notes on <a href=\"../../../people/yuki.html\">Yuki<\/a><\/span><\/h3><p class=\"setup\">Sits in front of Kiyotaka at dinner and, in a first, speaks to another child.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/index.html#shiro\">Shiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;I don&#x27;t like it…&quot;<span class=\"pg\">p.144<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;Kiyotaka, do you like it?&quot;<span class=\"pg\">p.145<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;Yeah. I&#x27;m not tired, but I somehow tripped. It&#x27;s a bit strange, isn&#x27;t it?&quot;<span class=\"pg\">p.146<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> The first child to initiate conversation and to display a spontaneous emotion — after tripping and being caught by Kiyotaka, she makes a &quot;smile,&quot; an expression never taught in the White Room but instinctive to humans.<span class=\"pg\">p.144–148<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Sits in front of him; asks if he likes carrots and trips before him, prompting his analysis of her unfamiliar expression.<span class=\"pg\">p.144–148<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiro<\/b> Her carrot question is answered by Shiro instead of Kiyotaka.<span class=\"pg\">p.145<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p149-1","v":"y0","y":0,"o":36,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the daily schedule at age five recalls the strict daily routine in the latter half of their fifth year  7 00 am   an inorganic mechanical voice announces  time to wake up  alarm exact to the second  staff remove the electrodes attached to them  immediate health check   height and weight changes  then bathroom  urine tests once a month and a small blood draw  staff leave without greetings  hydrate  thirty minutes of basic warmup training  record daily physical data such as grip strength  then training room with set quotas separated by gender   those who can t comply are barred from the room the next day  by 8 00 am   breakfast  nutrition focused  evolved into supplements and nutrition blocks  taste and preference irrelevant  eaten in the order served  subjects  language arts  mathematics  economics  political science  with brief breaks until noon  similar lunch  studies at desks until 5 00 pm  then physical education  everything ends at 7 00 pm  after dinner  bath and physical exam at 9 00 pm   a thirty minute  meeting  for children only  no educators  to reflect on the day  topics not freely chosen  adults intervene only for  unnecessary chatter  silence permitted  conversations overheard   part of the curriculum with no assigned quota  never spoke voluntarily in all this time  always just listened during the  meeting","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p149-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p149-1\">The daily schedule at age five<\/a><\/span><span class=\"meta\">Side stories · p.149–150<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls the strict daily routine in the latter half of their fifth year.<\/p><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> 7:00 AM — an inorganic mechanical voice announces &quot;Time to wake up,&quot; alarm exact to the second; staff remove the electrodes attached to them.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Immediate health check — height and weight changes; then bathroom; urine tests once a month and a small blood draw; staff leave without greetings.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Hydrate, thirty minutes of basic warmup training, record daily physical data such as grip strength, then training room with set quotas separated by gender — those who can&#x27;t comply are barred from the room the next day.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> By 8:00 AM — breakfast, nutrition-focused, evolved into supplements and nutrition blocks; taste and preference irrelevant, eaten in the order served.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Subjects: language arts, mathematics, economics, political science, with brief breaks until noon; similar lunch; studies at desks until 5:00 PM, then physical education; everything ends at 7:00 PM.<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> After dinner, bath and physical exam at 9:00 PM — a thirty-minute &quot;meeting&quot; for children only, no educators, to reflect on the day; topics not freely chosen, adults intervene only for &quot;unnecessary chatter,&quot; silence permitted, conversations overheard — part of the curriculum with no assigned quota.<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Never spoke voluntarily in all this time; always just listened during the &quot;meeting.&quot;<span class=\"pg\">p.149–150<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p144-1\">← Before: Yuki, carrots, and the first smile<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p152-1\">→ After: Deliberately scoring 80 to keep the ceiling low<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p152-1","v":"y0","y":0,"o":36,"k":"narration","w":"suzukake-tanji ishida-yuusuke ayanokouji-kiyotaka","q":"ayanokoji kiyotaka deliberately scoring 80 to keep the ceiling low recalls the  thinning out    as studies grew harder by two or three levels  children fell behind and were gradually removed  the special high difficulty exam s difficulty was set to the top score   a perfect score raised the ceiling and forced low scorers to struggle more next time  a sub perfect top score lowered it  trivial calculation errors  careless oversights and excuses were unacceptable  children repeatedly checked papers even after finishing  he had already filled every answer and stared ahead  the questions and answers  etched word for word  in his mind  he intentionally held back to score eighty points  an adult representative summoned him to a small private room after glancing at his paper   no   i wasn t instructed not to   in the first place  i ve never once recognized the other children around me as comrades   it was more time efficient to leave it blank   i won t make a mistake   if i hadn t held back  the percentage of children dropping out would have been much higher than it is now   no  losing experience that s how i thought of it   i want to know what the weak can see and feel  the instructor s lines   calling his name   it is foolish not to use the power you have   leave the room   why did you hold back  the accusation of camaraderie  and the warning that knowledge fades   are untagged in the corpus  no  says  row is claimed for them  he held back not from camaraderie  which he denies  but to gain data on weaker children and because writing answers he already knew was inefficient   a reason the instructors had never considered  begins to dislike the instructor who lectures him  understands yuki s aversion to carrots as a comparable irrational feeling  suzukake argues for observing him    if he does something we hadn t even considered  that s exactly what we hoped for  ishida is among the researchers who question his deliberate underperformance  another boy  sobbing  keeps writing after the buzzer and is dragged out screaming that he doesn t want to drop out  scattering gastric fluid over his paper  neck and clothes   though no one could drop out on that exam  most children just stare ahead","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p152-1\">Deliberately scoring 80 to keep the ceiling low<\/a><\/span><span class=\"meta\">Side stories · p.152–157<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls the &quot;thinning out&quot; — as studies grew harder by two or three levels, children fell behind and were gradually removed.<\/p><p class=\"with\">with <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a> · <a href=\"../../../people/index.html#ishida-yuusuke\">Ishida Yūsuke<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;No.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I wasn&#x27;t instructed not to.&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;In the first place, I&#x27;ve never once recognized the other children around me as comrades.&quot;<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The special high-difficulty exam&#x27;s difficulty was set to the top score — a perfect score raised the ceiling and forced low scorers to struggle more next time; a sub-perfect top score lowered it.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Trivial calculation errors, careless oversights and excuses were unacceptable; children repeatedly checked papers even after finishing. He had already filled every answer and stared ahead, the questions and answers &quot;etched word for word&quot; in his mind.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He intentionally held back to score eighty points; an adult representative summoned him to a small private room after glancing at his paper.<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;It was more time-efficient to leave it blank.&quot;<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I won&#x27;t make a mistake.&quot;<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;If I hadn&#x27;t held back, the percentage of children dropping out would have been much higher than it is now.&quot;<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;No. Losing experience—that&#x27;s how I thought of it.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I want to know what the weak can see and feel.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The instructor&#x27;s lines — calling his name, &quot;it is foolish not to use the power you have,&quot; &quot;leave the room,&quot; &quot;why did you hold back,&quot; the accusation of camaraderie, and the warning that knowledge fades — are untagged in the corpus; no `[says]` row is claimed for them.<span class=\"pg\">p.154–156<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> He held back not from camaraderie (which he denies) but to gain data on weaker children and because writing answers he already knew was inefficient — a reason the instructors had never considered.<span class=\"pg\">p.152–156<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Begins to dislike the instructor who lectures him; understands Yuki&#x27;s aversion to carrots as a comparable irrational feeling.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Suzukake Tanji<\/b> Suzukake argues for observing him — &quot;if he does something we hadn&#x27;t even considered, that&#x27;s exactly what we hoped for.&quot;<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishida Yūsuke<\/b> Ishida is among the researchers who question his deliberate underperformance.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Another boy, sobbing, keeps writing after the buzzer and is dragged out screaming that he doesn&#x27;t want to drop out, scattering gastric fluid over his paper, neck and clothes — though no one could drop out on that exam. Most children just stare ahead.<span class=\"pg\">p.157<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p149-1\">← Before: The daily schedule at age five<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p158-1\">→ After: The &quot;Travel&quot; virtual class and the odd instructor<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p158-1","v":"y0","y":0,"o":36,"k":"","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the  travel  virtual class and the odd instructor recalls the  travel  class  introduced the year they turned six  run once or twice a month for half a day using a virtual console  the class taught about places like new york and hawaii  previously known only from materials  used goggles and a virtual console  and doubled as observation insight training  the instructor announces an  equipment malfunction  ending the virtual session  then a new instructor appears for one on one sessions with  ten seconds per turn  and a demonstration to observe   the translation leaves these lines untagged  no  says  row is claimed  notes the session s abrupt end and the unfamiliar one on one format as curriculum detail","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p158-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p158-1\">The &quot;Travel&quot; virtual class and the odd instructor<\/a><\/span><span class=\"meta\">Side stories · p.158–166<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Recalls the &quot;Travel&quot; class, introduced the year they turned six, run once or twice a month for half a day using a virtual console.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> The class taught about places like New York and Hawaii, previously known only from materials; used goggles and a virtual console, and doubled as observation/insight training.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The instructor announces an &quot;equipment malfunction&quot; ending the virtual session, then a new instructor appears for one-on-one sessions with &quot;ten seconds per turn&quot; and a demonstration to observe — the translation leaves these lines untagged; no `[says]` row is claimed.<span class=\"pg\">p.159–160<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Notes the session&#x27;s abrupt end and the unfamiliar one-on-one format as curriculum detail.<span class=\"pg\">p.158–166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p152-1\">← Before: Deliberately scoring 80 to keep the ceiling low<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p167-1\">→ After: The conversation with Yuki about smiling<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p167-1","v":"y0","y":0,"o":36,"k":"narration","w":"yuki ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the conversation with yuki about smiling  i don t know  but i feel like i can laugh again if i m near you  kiyotaka   i can t understand that  yuki says she can t laugh now  though she laughed before  kiyotaka notes he himself doesn t know how to smile    i hadn t learned the basics of emotions  he speculates that laughter may require being near a specific person  noting instructors show anger and smiles toward others  concludes emotions are probably unnecessary since he wasn t taught them","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p167-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p167-1\">The conversation with Yuki about smiling<\/a><\/span><span class=\"meta\">Side stories · p.167–168<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/yuki.html\">Yuki<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Yuki<\/b> &quot;I don&#x27;t know, but I feel like I can laugh again if I&#x27;m near you, Kiyotaka.&quot;<span class=\"pg\">p.167<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I can&#x27;t understand that.&quot;<span class=\"pg\">p.167<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Yuki says she can&#x27;t laugh now, though she laughed before; Kiyotaka notes he himself doesn&#x27;t know how to smile — &quot;I hadn&#x27;t learned the basics of emotions.&quot;<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> He speculates that laughter may require being near a specific person, noting instructors show anger and smiles toward others; concludes emotions are probably unnecessary since he wasn&#x27;t taught them.<span class=\"pg\">p.167–168<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p158-1\">← Before: The &quot;Travel&quot; virtual class and the odd instructor<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p172-1\">→ After: Arisu Sakayanagi observes the White Room<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p172-1","v":"y0","y":0,"o":36,"k":"narration","w":"sakayanagi-arisu sakayanagi-narimori ayanokouji-kiyotaka","q":"ayanokoji kiyotaka arisu sakayanagi observes the white room arisu  held by her father  watches the white room students through a one way mirror in the observation room  sakayanagi tells his daughter  these children might someday be responsible for japan s future  she presses her hands to the glass  staring for five then ten minutes without tiring   an experiment to artificially create geniuses  how could i not be interested   from a humanitarian perspective  people are likely to criticize it from all sides   ultimately  i think the children who stand out just have excellent dna   that child  he s been handling all the tasks calmly and effortlessly since earlier   he s spent his entire life in this facility since he was born  the first thing he saw wasn t his mother or father  but the facility s white ceiling   do you dislike this facility  father   i m not sure  i can t honestly support it   rest assured  i will shatter it  i will prove that a genius is not determined by their education  but by the moment they re born   by the way  father  i think i ll try to learn chess  arisu notices kiyotaka s unusual aura  narimori pities him as the ideal subject  and arisu concludes the survivors and dropouts exist for future children   a fight decided fifty or even a hundred years from now  a young girl with an adult like perspective who resolves to  shatter  the white room and takes up chess   the origin of her rivalry with kiyotaka  watches with his daughter  atsuomi monitors their conversation via camera audio but concludes it was  an unnecessary concern","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p172-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p172-1\">Arisu Sakayanagi observes the White Room<\/a><\/span><span class=\"meta\">Side stories · p.172–176<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Arisu, held by her father, watches the White Room students through a one-way mirror in the observation room.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Sakayanagi Arisu<\/b> &quot;An experiment to artificially create geniuses. How could I not be interested?&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Sakayanagi Arisu<\/b> &quot;From a humanitarian perspective, people are likely to criticize it from all sides.&quot;<span class=\"pg\">p.173<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Sakayanagi Arisu<\/b> &quot;Ultimately, I think the children who stand out just have excellent DNA.&quot;<span class=\"pg\">p.175<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Sakayanagi tells his daughter &quot;these children might someday be responsible for Japan&#x27;s future&quot;; she presses her hands to the glass, staring for five then ten minutes without tiring.<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;That child, he&#x27;s been handling all the tasks calmly and effortlessly since earlier.&quot;<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;He&#x27;s spent his entire life in this facility since he was born. The first thing he saw wasn&#x27;t his mother or father, but the facility&#x27;s white ceiling.&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Do you dislike this facility, Father?&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;m not sure… I can&#x27;t honestly support it.&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Rest assured. I will shatter it. I will prove that a genius is not determined by their education, but by the moment they&#x27;re born.&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;By the way, Father. I think I&#x27;ll try to learn chess…&quot;<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Arisu notices Kiyotaka&#x27;s unusual aura; Narimori pities him as the ideal subject, and Arisu concludes the survivors and dropouts exist for future children — a fight decided fifty or even a hundred years from now.<span class=\"pg\">p.175–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> A young girl with an adult-like perspective who resolves to &quot;shatter&quot; the White Room and takes up chess — the origin of her rivalry with Kiyotaka.<span class=\"pg\">p.172–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> Watches with his daughter; Atsuomi monitors their conversation via camera audio but concludes it was &quot;an unnecessary concern.&quot;<span class=\"pg\">p.172–176<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p167-1\">← Before: The conversation with Yuki about smiling<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p178-1\">→ After: Yuki fails and leaves<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p178-1","v":"y0","y":0,"o":36,"k":"narration","w":"yuki ayanokouji-kiyotaka","q":"ayanokoji kiyotaka yuki fails and leaves waits as papers are graded  yuki s small back trembles in the front row   please wait   yuki seemed unwell since before noon  she was restless during the test  and perhaps she couldn t demonstrate her abilities due to reasons other than her capabilities  he speaks without permission and is kicked by the instructor  the adults notice bleeding   the onset of menstruation  unusual this early  normally age nine at the earliest  likely from stress  she also has a fever  the instructor orders her to the infirmary  as she leaves crying  she looks at kiyotaka but he doesn t meet her gaze  from that day on  yuki never returned  he provokes a rookie instructor into a wild swing that he dodges  another instructor stops the  rookie    he wanted to test and either properly educate or dispose of the new instructor  detects yuki s irregular condition through observation and challenges the instructor s authority deliberately   testing those who would use him  tries to argue for her  she leaves crying and never returns","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p178-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p178-1\">Yuki fails and leaves<\/a><\/span><span class=\"meta\">Side stories · p.178–185<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Waits as papers are graded; Yuki&#x27;s small back trembles in the front row.<\/p><p class=\"with\">with <a href=\"../../../people/yuki.html\">Yuki<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Please wait.&quot;<span class=\"pg\">p.184<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yuki seemed unwell since before noon. She was restless during the test, and perhaps she couldn&#x27;t demonstrate her abilities due to reasons other than her capabilities—&quot;<span class=\"pg\">p.184<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> He speaks without permission and is kicked by the instructor; the adults notice bleeding — the onset of menstruation, unusual this early (normally age nine at the earliest), likely from stress; she also has a fever.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The instructor orders her to the infirmary; as she leaves crying, she looks at Kiyotaka but he doesn&#x27;t meet her gaze; from that day on, Yuki never returned.<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He provokes a rookie instructor into a wild swing that he dodges; another instructor stops the &quot;rookie&quot; — he wanted to test and either properly educate or dispose of the new instructor.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Detects Yuki&#x27;s irregular condition through observation and challenges the instructor&#x27;s authority deliberately — testing those who would use him.<span class=\"pg\">p.184–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yuki<\/b> Tries to argue for her; she leaves crying and never returns.<span class=\"pg\">p.178–185<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p172-1\">← Before: Arisu Sakayanagi observes the White Room<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p186-1\">→ After: Shiro&#x27;s farewell: wanting freedom<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p186-1","v":"y0","y":0,"o":36,"k":"narration","w":"shiro ayanokouji-kiyotaka","q":"ayanokoji kiyotaka shiro s farewell  wanting freedom with only him and shiro left  they begin a judo randori while the referee steps out   can i say something   it s been years since i last won against you in judo  hasn t it   i ve decided to leave this facility   that s why i m going to drop out voluntarily   i want to be free  i want friends   i ll go ahead  let s meet again someday  kiyotaka   in the end  i lost again  huh   goodbye  shiro   goodbye  kiyotaka  shiro  hurt in boxing  karate and jeet kune do too  wants the real world rather than a virtual one  kiyotaka cannot understand wanting freedom or friends  in the final match kiyotaka resolves to out exert him  if the opponent exerted 140  effort  i would exert 150  and slams him onto the tatami  they are watched from the second floor beyond the glass  cannot comprehend shiro s desire for freedom or the outside world   he is not dissatisfied  and intellectual curiosity drives him to stay and keep learning  his last real rival  their final randori and farewell   shiro drops out soon after","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p186-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p186-1\">Shiro&#x27;s farewell: wanting freedom<\/a><\/span><span class=\"meta\">Side stories · p.186–191<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">With only him and Shiro left, they begin a judo randori while the referee steps out.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#shiro\">Shiro<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Shiro<\/b> &quot;Can I say something?&quot;<span class=\"pg\">p.186<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Shiro<\/b> &quot;It&#x27;s been years since I last won against you in judo, hasn&#x27;t it?&quot;<span class=\"pg\">p.186<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Shiro<\/b> &quot;I&#x27;ve decided to leave this facility.&quot;<span class=\"pg\">p.187<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;That&#x27;s why I&#x27;m going to drop out voluntarily.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I want to be free. I want friends.&quot;<span class=\"pg\">p.187<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ll go ahead. Let&#x27;s meet again someday, Kiyotaka.&quot;<span class=\"pg\">p.190<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;In the end… I lost again, huh?&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Goodbye, Shiro.&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Goodbye, Kiyotaka.&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Shiro, hurt in boxing, karate and Jeet Kune Do too, wants the real world rather than a virtual one; Kiyotaka cannot understand wanting freedom or friends. In the final match Kiyotaka resolves to out-exert him (&quot;if the opponent exerted 140% effort, I would exert 150%&quot;) and slams him onto the tatami; they are watched from the second floor beyond the glass.<span class=\"pg\">p.186–190<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cannot comprehend Shiro&#x27;s desire for freedom or the outside world — he is not dissatisfied, and intellectual curiosity drives him to stay and keep learning.<span class=\"pg\">p.187–191<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiro<\/b> His last real rival; their final randori and farewell — Shiro drops out soon after.<span class=\"pg\">p.186–191<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p178-1\">← Before: Yuki fails and leaves<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p192-1\">→ After: The baton fight against grown men; father revealed<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p192-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-atsuomi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the baton fight against grown men  father revealed at age nine  after defeating all the martial arts instructors  he is ordered to fight multiple grown men in  actual combat   kiyotaka  from now on  you will fight multiple people in actual combat format   and you don t need to hold back at all  you can go as far as killing   i was ordered to kill   you probably understand by now  but i am the head of the white room  and i m also your biological father   i know   when i was four  i remember hearing it while the instructors were talking   you are special to me  chooses a collapsing baton  30 cm  extends to  60 cm  for reach  shatters the last man s leg and aims a head blow to knock him out  stopped by  stop  the men are carried out on stretchers  atsuomi tells him alone that he is his biological father  kiyotaka had known since age four    a father to me  that was nothing special  his biological father reveals himself  kiyotaka is unmoved  follows the kill order literally and without emotion  treats the father reveal as  just a fact","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p192-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p192-1\">The baton fight against grown men; father revealed<\/a><\/span><span class=\"meta\">Side stories · p.192–196<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At age nine, after defeating all the martial-arts instructors, he is ordered to fight multiple grown men in &quot;actual combat.&quot;<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Kiyotaka, from now on, you will fight multiple people in actual combat format.&quot;<span class=\"pg\">p.192<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;And you don&#x27;t need to hold back at all. You can go as far as killing.&quot;<span class=\"pg\">p.192<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I was ordered to kill.&quot;<span class=\"pg\">p.192<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;You probably understand by now, but I am the head of the White Room, and I&#x27;m also your biological father.&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I know.&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;When I was four. I remember hearing it while the instructors were talking.&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;You are special to me.&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Chooses a collapsing baton (~30 cm, extends to ~60 cm) for reach; shatters the last man&#x27;s leg and aims a head blow to knock him out, stopped by &quot;STOP!&quot;; the men are carried out on stretchers.<span class=\"pg\">p.193–194<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Atsuomi tells him alone that he is his biological father; Kiyotaka had known since age four — &quot;a father—to me, that was nothing special.&quot;<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> His biological father reveals himself; Kiyotaka is unmoved.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Follows the kill order literally and without emotion; treats the father reveal as &quot;just a fact.&quot;<span class=\"pg\">p.192–196<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p186-1\">← Before: Shiro&#x27;s farewell: wanting freedom<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p197-1\">→ After: The researchers on his lack of emotion<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p197-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the researchers on his lack of emotion  that is both kiyotaka s strength and a permanent weakness   it s too late to instill emotions in the white room now  if so  we have no choice but to significantly change his environment   kiyotaka is clearly an anomaly  this isn t just favoritism because he s your son  ishida and atsuomi discuss him in front of him   his pulse barely changes even in conversation or combat  he has  almost nothing  in the way of emotion  but can skillfully lie and disguise himself  atsuomi orders them to investigate why he has no limits  paying them enough to pursue it  he listens without reaction   praise or criticism doesn t matter   everything comes down to whether you drop out","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p197-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p197-1\">The researchers on his lack of emotion<\/a><\/span><span class=\"meta\">Side stories · p.197–198<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;That is both Kiyotaka&#x27;s strength and a permanent weakness.&quot;<span class=\"pg\">p.197<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;It&#x27;s too late to instill emotions in the White Room now. If so, we have no choice but to significantly change his environment.&quot;<span class=\"pg\">p.197<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Kiyotaka is clearly an anomaly. This isn&#x27;t just favoritism because he&#x27;s your son.&quot;<span class=\"pg\">p.198<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Ishida and Atsuomi discuss him in front of him — his pulse barely changes even in conversation or combat; he has &quot;almost nothing&quot; in the way of emotion, but can skillfully lie and disguise himself. Atsuomi orders them to investigate why he has no limits, paying them enough to pursue it.<span class=\"pg\">p.197–198<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> He listens without reaction — praise or criticism doesn&#x27;t matter; &quot;everything comes down to whether you drop out.&quot;<span class=\"pg\">p.198<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p192-1\">← Before: The baton fight against grown men; father revealed<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p251-1\">→ After: The Yuki reunion; first day outside<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p199-1","v":"y0","y":0,"o":36,"k":"narration","w":"naoe-sensei kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi naoe withdraws  the white room scrapped at the ryoutei in sasagawa on a snowy january night  waits with kamogawa to report the white room s success to naoe sensei  tokyo is struck by unusually heavy snow  the garden visible from the corridor window is lit up  the meeting is over ten years after they first waited in the cold for naoe  kamogawa s father died of a myocardial infarction around this time last year  delivering the white room announcement had been kamogawa s goal   just achieve results that reach the heavens  don t be satisfied with just today  kamogawa   sorry to keep you waiting    naoe  arriving only  10 minutes late  i ve decided to withdraw my candidacy for the next party leader election   the calculations show that i m short by twenty to thirty votes   yet  kijima hasn t changed at all  he s taking politics seriously   for kijima  you ve become an eyesore   it s decided  it s a blank slate   if kijima acknowledges that you have no fangs  i ll put you forward again   don t joke with me  naoe withdraws because he is 20 30 votes short and the opposition plus kijima s clean record make running futile  he supports kijima to keep his position  and scraps the white room because atsuomi s flashy financial yakuza dealings have made him a liability  for the first time loses composure    don t joke with me    after over a decade of sacrificing everything for the project  resolves not to let it go to waste  his mentor and patron abandons him and the white room  atsuomi is ordered to  lay low  shares the shock  kamogawa s joy turns to despair at the  blank slate","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p199-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p199-1\">Naoe withdraws; the White Room scrapped<\/a><\/span><span class=\"meta\">Side stories · p.199–207<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">At the ryoutei in Sasagawa on a snowy January night, waits with Kamogawa to report the White Room&#x27;s success to Naoe-sensei.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Just achieve results that reach the heavens. Don&#x27;t be satisfied with just today, Kamogawa.&quot;<span class=\"pg\">p.200<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Sorry to keep you waiting.&quot; — Naoe, arriving only ~10 minutes late<span class=\"pg\">p.201<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I&#x27;ve decided to withdraw my candidacy for the next party leader election.&quot;<span class=\"pg\">p.202<\/span><\/li><\/ul><details class=\"more\"><summary>12 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Tokyo is struck by unusually heavy snow; the garden visible from the corridor window is lit up; the meeting is over ten years after they first waited in the cold for Naoe.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Kamogawa&#x27;s father died of a myocardial infarction around this time last year; delivering the White Room announcement had been Kamogawa&#x27;s goal.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;The calculations show that I&#x27;m short by twenty to thirty votes.&quot;<span class=\"pg\">p.203<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Yet, Kijima hasn&#x27;t changed at all. He&#x27;s taking politics seriously.&quot;<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;For Kijima, you&#x27;ve become an eyesore.&quot;<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;It&#x27;s decided. It&#x27;s a blank slate.&quot;<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;If Kijima acknowledges that you have no fangs, I&#x27;ll put you forward again.&quot;<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;—Don&#x27;t joke with me.&quot;<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Naoe withdraws because he is 20–30 votes short and the opposition plus Kijima&#x27;s clean record make running futile; he supports Kijima to keep his position, and scraps the White Room because Atsuomi&#x27;s flashy financial/yakuza dealings have made him a liability.<span class=\"pg\">p.202–207<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> For the first time loses composure — &quot;Don&#x27;t joke with me&quot; — after over a decade of sacrificing everything for the project; resolves not to let it go to waste.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> His mentor and patron abandons him and the White Room; Atsuomi is ordered to &quot;lay low.&quot;<span class=\"pg\">p.199–207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Shares the shock; Kamogawa&#x27;s joy turns to despair at the &quot;blank slate.&quot;<span class=\"pg\">p.199–207<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p129-1\">← Before: Sakayanagi&#x27;s phone call: offering to take his child<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p219-1\">→ After: The funding party: President Amasawa<\/button><\/div><\/article>"},{"i":"sc-amasawa-president-y0-p219-1","v":"y0","y":0,"o":36,"k":"narration","w":"amasawa-ichika ayanokouji-atsuomi amasawa-president","q":"amasawa  president  president amasawa  treating the white room as daycare  absolutely  what she wants is for our child to be born that s her goal  she has no intention of becoming a mother and raising the child   why not  she gets to have a child  i can offload an inconvenient child to the white room  and you get to profit from it   this year  i ll double last year s amount  i ll give one hundred million   of course  sending her regular photos should satisfy her   as for the future  please do as you like  ayanokouji sensei  after all  that was a test tube baby  and i don t really feel like she s my own child  a callous billionaire   a  hawaii enthusiast  whose wife suspects cheating  offers  100 million for his unborn child s placement  never visits his daughter  and hums happily after the deal  his test tube daughter in the white room  he feels no paternal connection  negotiates white room financing and placement of another child","h":"<article class=\"card\" id=\"sc-amasawa-president-y0-p219-1\"><h3><span class=\"ttl\">President Amasawa: treating the White Room as daycare<\/span><span class=\"meta\">Side stories · p.219–223<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#amasawa-president\">Amasawa (President)<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Amasawa (President)<\/b> &quot;Absolutely. What she wants is for our child to be born—that&#x27;s her goal. She has no intention of becoming a mother and raising the child.&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Amasawa (President)<\/b> &quot;Why not? She gets to have a child, I can offload an inconvenient child to the White Room, and you get to profit from it.&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Amasawa (President)<\/b> &quot;This year, I&#x27;ll double last year&#x27;s amount. I&#x27;ll give one hundred million.&quot;<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Of course. Sending her regular photos should satisfy her.&quot;<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;As for the future, please do as you like, Ayanokouji-sensei. After all, that was a test-tube baby, and I don&#x27;t really feel like she&#x27;s my own child.&quot;<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> A callous billionaire — a &quot;Hawaii enthusiast&quot; whose wife suspects cheating; offers ¥100 million for his unborn child&#x27;s placement, never visits his daughter, and hums happily after the deal.<span class=\"pg\">p.219–223<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> His test-tube daughter in the White Room; he feels no paternal connection.<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Negotiates White Room financing and placement of another child.<span class=\"pg\">p.219–223<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p219-1","v":"y0","y":0,"o":36,"k":"narration","w":"amasawa-president amasawa-ichika ayanokouji-atsuomi","q":"ayanokoji atsuomi the funding party  president amasawa at a party  negotiates with president amasawa  who wants his unborn child placed in the white room   we re already taking care of your daughter in the white room  president amasawa   this year  i ll double last year s amount  i ll give one hundred million    amasawa  unless there s a special reason  visits are basically impossible  you can only meet your children regularly after they become adults or leave the white room   as for the future  please do as you like  ayanokouji sensei  after all  that was a test tube baby  and i don t really feel like she s my own child    amasawa amasawa s wife wants to give birth in japan  she is a  hawaii enthusiast  and suspects cheating  he treats the white room as convenient daycare  offers  100 million  never visits his daughter  and hums happily  maintains control of tone with a billionaire  ensuring he isn t offended  sees such children as profitable  no danger additions  negotiates financing  the president entrusts another child to the white room  amasawa s test tube daughter  the second most developed fifth generation student","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p219-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p219-1\">The funding party: President Amasawa<\/a><\/span><span class=\"meta\">Side stories · p.219–223<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">At a party, negotiates with President Amasawa, who wants his unborn child placed in the White Room.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#amasawa-president\">Amasawa (President)<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;We&#x27;re already taking care of your daughter in the White Room, President Amasawa.&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;This year, I&#x27;ll double last year&#x27;s amount. I&#x27;ll give one hundred million.&quot; — Amasawa<span class=\"pg\">p.221<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Unless there&#x27;s a special reason, visits are basically impossible. You can only meet your children regularly after they become adults or leave the White Room.&quot;<span class=\"pg\">p.222<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;As for the future, please do as you like, Ayanokouji-sensei. After all, that was a test-tube baby, and I don&#x27;t really feel like she&#x27;s my own child.&quot; — Amasawa<span class=\"pg\">p.222<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Amasawa&#x27;s wife wants to give birth in Japan (she is a &quot;Hawaii enthusiast&quot;) and suspects cheating; he treats the White Room as convenient daycare, offers ¥100 million, never visits his daughter, and hums happily.<span class=\"pg\">p.221–223<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Maintains control of tone with a billionaire, ensuring he isn&#x27;t offended; sees such children as profitable, no-danger additions.<span class=\"pg\">p.219–223<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa (President)<\/b> Negotiates financing; the president entrusts another child to the White Room.<span class=\"pg\">p.219–223<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Amasawa&#x27;s test-tube daughter, the second most developed fifth-generation student.<span class=\"pg\">p.222–223<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p199-1\">← Before: Naoe withdraws; the White Room scrapped<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p232-1\">→ After: The children&#x27;s dispute; Kanzaki and Ishigami; Sakayanagi&#x27;s farewell<\/button><\/div><\/article>"},{"i":"sc-fuji-y0-p224-1","v":"y0","y":0,"o":36,"k":"narration","w":"ishigami-kyou nogi fuji","q":"fuji fuji  the falsely accused boy is surrounded by nogi s group and accused of lying about receiving kazuya s autograph   i really did get it  he signed a soccer ball for me   like i said  i  i didn t lie  timid and tearful but stubbornly insists on the truth even while being pressured to prostrate himself   which draws ishigami s defense  defends him when others won t  his accuser","h":"<article class=\"card\" id=\"sc-fuji-y0-p224-1\"><h3><span class=\"ttl\">Fuji, the falsely accused boy<\/span><span class=\"meta\">Side stories · p.224–230<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#fuji\">Fuji<\/a><\/span><\/h3><p class=\"setup\">Is surrounded by Nogi&#x27;s group and accused of lying about receiving Kazuya&#x27;s autograph.<\/p><p class=\"with\">with <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a> · <a href=\"../../../people/index.html#nogi\">Nogi<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Fuji<\/b> &quot;I really did get it. He signed a soccer ball for me…!&quot;<span class=\"pg\">p.225<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Fuji<\/b> &quot;Like I said, I… I didn&#x27;t lie…!&quot;<span class=\"pg\">p.226<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Timid and tearful but stubbornly insists on the truth even while being pressured to prostrate himself — which draws Ishigami&#x27;s defense.<span class=\"pg\">p.225–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> Defends him when others won&#x27;t.<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nogi<\/b> His accuser.<span class=\"pg\">p.225–230<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ishigami-kyou-y0-p225-1","v":"y0","y":0,"o":36,"k":"narration","w":"fuji nogi ishigami-gorou ayanokouji-kiyotaka ishigami-kyou","q":"ishigami kyo ishigami defends fuji and outwits nogi a sixth child who arrives late  defends the accused fuji against nogi s group   fuji isn t lying that s what i think   i m not defending him for no reason  i just think it s true   when you re going to hit someone  it s better to grab them by the collar first so they can t escape   i m not bragging  and i ve never fought before  i m sure you could beat me  however  i can run away   help me  someone  please help   i noticed early on that fuji was calling for help  yet you just stood by and observed  i couldn t be sure you d be on our side  reasons that fuji has no motive to keep lying while surrounded  dismantles nogi s claim that he was the first to receive an autograph  then goads nogi into grabbing his collar and calls for help with the adults watching   provoking a scene that would humiliate the powerful father  exceptionally clever and calm   a cut above the other children  avoids conflict when only he is involved  it s just a hassle to get angry at every low level comment  but defends a friend  deliberately doesn t call on atsuomi  whom he saw only observing  defends him against the bullying  outwits him in the confrontation  his father  president of the ishigami group  gently scolded for causing trouble  questions why atsuomi didn t help  his father asks atsuomi to take him into politics later","h":"<article class=\"card\" id=\"sc-ishigami-kyou-y0-p225-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishigami-kyou.html#sc-ishigami-kyou-y0-p225-1\">Ishigami defends Fuji and outwits Nogi<\/a><\/span><span class=\"meta\">Side stories · p.225–233<\/span><span class=\"by\">notes on <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a><\/span><\/h3><p class=\"setup\">A sixth child who arrives late; defends the accused Fuji against Nogi&#x27;s group.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#fuji\">Fuji<\/a> · <a href=\"../../../people/index.html#nogi\">Nogi<\/a> · <a href=\"../../../people/index.html#ishigami-gorou\">Ishigami Gorou<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;Fuji isn&#x27;t lying—that&#x27;s what I think.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;I&#x27;m not defending him for no reason. I just think it&#x27;s true.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;When you&#x27;re going to hit someone, it&#x27;s better to grab them by the collar first so they can&#x27;t escape.&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;m not bragging, and I&#x27;ve never fought before. I&#x27;m sure you could beat me. However, I can run away.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Help me! Someone, please help!!&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I noticed early on that Fuji was calling for help, yet you just stood by and observed. I couldn&#x27;t be sure you&#x27;d be on our side.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reasons that Fuji has no motive to keep lying while surrounded, dismantles Nogi&#x27;s claim that he was the first to receive an autograph, then goads Nogi into grabbing his collar and calls for help with the adults watching — provoking a scene that would humiliate the powerful father.<span class=\"pg\">p.227–230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Exceptionally clever and calm — a cut above the other children; avoids conflict when only he is involved (&quot;it&#x27;s just a hassle to get angry at every low-level comment&quot;) but defends a friend; deliberately doesn&#x27;t call on Atsuomi, whom he saw only observing.<span class=\"pg\">p.225–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fuji<\/b> Defends him against the bullying.<span class=\"pg\">p.227<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nogi<\/b> Outwits him in the confrontation.<span class=\"pg\">p.229–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Gorou<\/b> His father, president of the Ishigami Group; gently scolded for causing trouble.<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions why Atsuomi didn&#x27;t help; his father asks Atsuomi to take him into politics later.<span class=\"pg\">p.232–233<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kanzaki-ryuuji-y0-p225-1","v":"y0","y":0,"o":36,"k":"narration","w":"fuji ishigami-kyou kanzaki-tomohiro ayanokouji-kiyotaka kanzaki-ryuuji","q":"kanzaki ryuji ryuuji at the party  the autograph dispute and the lecture present among the children disputing whether fuji received kazuya s autograph   it doesn t matter to me  whichever is fine   if i have to judge objectively  i think he s lying  it d be better to apologize sooner  objective and pragmatic   judges fuji is lying and urges apology given the numbers and physique against him  quiet and avert his gaze shy when introduced to atsuomi  judges him to be lying  calls him out as  exceptionally talented  can t help snapping at him  his father  president of kanzaki engineering  who dotes on him and touts his black belt level karate skill  is lectured by atsuomi about using one s power to help others   a calculated move to keep his father s investment  moved  he bows happily  atsuomi notices an inconsistency  the father claims ryuuji is black belt level in karate  yet ryuuji did little when fuji was bullied","h":"<article class=\"card\" id=\"sc-kanzaki-ryuuji-y0-p225-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kanzaki-ryuuji.html#sc-kanzaki-ryuuji-y0-p225-1\">Ryuuji at the party: the autograph dispute and the lecture<\/a><\/span><span class=\"meta\">Side stories · p.225–237<\/span><span class=\"by\">notes on <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/span><\/h3><p class=\"setup\">Present among the children disputing whether Fuji received Kazuya&#x27;s autograph.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#fuji\">Fuji<\/a> · <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a> · <a href=\"../../../people/index.html#kanzaki-tomohiro\">Kanzaki Tomohiro<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;It doesn&#x27;t matter to me. Whichever is fine.&quot;<span class=\"pg\">p.225<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kanzaki Ryūji<\/b> &quot;If I have to judge objectively, I think he&#x27;s lying. It&#x27;d be better to apologize sooner.&quot;<span class=\"pg\">p.225<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Objective and pragmatic — judges Fuji is lying and urges apology given the numbers and physique against him; quiet and avert-his-gaze shy when introduced to Atsuomi.<span class=\"pg\">p.225–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fuji<\/b> Judges him to be lying.<span class=\"pg\">p.225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> Calls him out as &quot;exceptionally talented&quot;; can&#x27;t help snapping at him.<span class=\"pg\">p.228<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Tomohiro<\/b> His father, president of Kanzaki Engineering, who dotes on him and touts his black-belt-level karate skill.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is lectured by Atsuomi about using one&#x27;s power to help others — a calculated move to keep his father&#x27;s investment; moved, he bows happily.<span class=\"pg\">p.236–237<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Atsuomi notices an inconsistency: the father claims Ryuuji is black-belt-level in karate, yet Ryuuji did little when Fuji was bullied.<span class=\"pg\">p.234<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nogi-y0-p225-1","v":"y0","y":0,"o":36,"k":"narration","w":"fuji ishigami-kyou nogi","q":"nogi nogi  the bullying leader leads the three boys accusing fuji of lying about the autograph   if you act all high and mighty  i ll ask my dad to ruin your parents  company   prostrate yourself  prostrate  apologize for lying and i ll forgive you   ha  look at this  a two shot with kazuya   i ll do as you wish  arrogant and boorish   boasts of his father s power as his own  demands fuji prostrate himself  and is easily baited by ishigami into a public humiliation  bullying target  is outwitted by him","h":"<article class=\"card\" id=\"sc-nogi-y0-p225-1\"><h3><span class=\"ttl\">Nogi, the bullying leader<\/span><span class=\"meta\">Side stories · p.225–230<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#nogi\">Nogi<\/a><\/span><\/h3><p class=\"setup\">Leads the three boys accusing Fuji of lying about the autograph.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#fuji\">Fuji<\/a> · <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Nogi<\/b> &quot;If you act all high and mighty, I&#x27;ll ask my dad to ruin your parents&#x27; company.&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Nogi<\/b> &quot;Prostrate yourself, prostrate. Apologize for lying and I&#x27;ll forgive you.&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Nogi<\/b> &quot;Ha! Look at this, a two-shot with Kazuya!&quot;<span class=\"pg\">p.228<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ll do as you wish!&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Arrogant and boorish — boasts of his father&#x27;s power as his own, demands Fuji prostrate himself, and is easily baited by Ishigami into a public humiliation.<span class=\"pg\">p.225–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fuji<\/b> Bullying target.<span class=\"pg\">p.225–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> Is outwitted by him.<span class=\"pg\">p.229–230<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p232-1","v":"y0","y":0,"o":36,"k":"narration","w":"ishigami-kyou kanzaki-ryuuji sakayanagi-narimori nogi fuji ayanokouji-atsuomi","q":"ayanokoji atsuomi the children s dispute  kanzaki and ishigami  sakayanagi s farewell watches a group of party children bullying one boy  fuji  over a kazuya autograph  five boys  three surround fuji  nogi the leader  ryuuji and ishigami also present  the leader demands a vote  ishigami defends fuji  reasons the claim of being the first to receive an autograph can t be proven  and tricks nogi into grabbing his collar before calling for help from adults   atsuomi notes ishigami deliberately didn t choose him because atsuomi had only observed   i noticed early on that fuji was calling for help  yet you just stood by and observed  i couldn t be sure you d be on our side    ishigami  if you don t have the power to help  you might as well just give up and run away  but if you do have the power and don t use it  then you re a fool   being associated with a man like me would pose many problems for you as the chairman of anhs   i have to solidify the white room and send personnel capable of overhauling the country s organizational structure  then  i plan to overturn that system from the ground up   good luck  sakayanagi  let s meet again someday  reads people sharply  gives ryuuji a calculated  lecture  in front of his father to keep kanzaki engineering s investment  and lays out a 10 20 year plan to overturn japan s seniority bound political system from within  the clever son of the ishigami group president  atsuomi is impressed by his calm and is asked  noncommittally  to take him into politics later  ryuuji  son of kanzaki tomohiro  atsuomi lectures him about using one s power to help others  becomes anhs chairman and must distance himself from atsuomi  they part on good terms  nogi pharmaceuticals  son  the bullying leader  the boy falsely accused of lying about the autograph","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p232-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p232-1\">The children&#x27;s dispute; Kanzaki and Ishigami; Sakayanagi&#x27;s farewell<\/a><\/span><span class=\"meta\">Side stories · p.232–240<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Watches a group of party children bullying one boy (Fuji) over a Kazuya autograph.<\/p><p class=\"with\">with <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a> · <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/sakayanagi-narimori.html\">Sakayanagi Narimori<\/a> · <a href=\"../../../people/index.html#nogi\">Nogi<\/a> · <a href=\"../../../people/index.html#fuji\">Fuji<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I noticed early on that Fuji was calling for help, yet you just stood by and observed. I couldn&#x27;t be sure you&#x27;d be on our side.&quot; — Ishigami<span class=\"pg\">p.232<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;If you don&#x27;t have the power to help, you might as well just give up and run away. But if you do have the power and don&#x27;t use it, then you&#x27;re a fool.&quot;<span class=\"pg\">p.236<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;Being associated with a man like me would pose many problems for you as the chairman of ANHS.&quot;<span class=\"pg\">p.238<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Five boys; three surround Fuji, Nogi the leader, Ryuuji and Ishigami also present; the leader demands a vote; Ishigami defends Fuji, reasons the claim of being the first to receive an autograph can&#x27;t be proven, and tricks Nogi into grabbing his collar before calling for help from adults — Atsuomi notes Ishigami deliberately didn&#x27;t choose him because Atsuomi had only observed.<span class=\"pg\">p.224–230<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I have to solidify the White Room and send personnel capable of overhauling the country&#x27;s organizational structure. Then, I plan to overturn that system from the ground up.&quot;<span class=\"pg\">p.239<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Good luck, Sakayanagi. Let&#x27;s meet again someday.&quot;<span class=\"pg\">p.240<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reads people sharply, gives Ryuuji a calculated &quot;lecture&quot; in front of his father to keep Kanzaki Engineering&#x27;s investment, and lays out a 10–20 year plan to overturn Japan&#x27;s seniority-bound political system from within.<span class=\"pg\">p.232–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> The clever son of the Ishigami Group president; Atsuomi is impressed by his calm and is asked (noncommittally) to take him into politics later.<span class=\"pg\">p.227–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Ryuuji, son of Kanzaki Tomohiro; Atsuomi lectures him about using one&#x27;s power to help others.<span class=\"pg\">p.234–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Narimori<\/b> Becomes ANHS chairman and must distance himself from Atsuomi; they part on good terms.<span class=\"pg\">p.238–240<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nogi<\/b> Nogi Pharmaceuticals&#x27; son, the bullying leader.<span class=\"pg\">p.225–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fuji<\/b> The boy falsely accused of lying about the autograph.<span class=\"pg\">p.224–230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p219-1\">← Before: The funding party: President Amasawa<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p247-1\">→ After: Returning to Tokyo; preparing the comeback<\/button><\/div><\/article>"},{"i":"sc-ishigami-gorou-y0-p232-1","v":"y0","y":0,"o":36,"k":"narration","w":"ishigami-kyou ayanokouji-kiyotaka ishigami-gorou","q":"ishigami gorou president ishigami  the doting father appears flustered after his son ishigami is involved in the party dispute   hey  kyou  you re not causing any trouble for ayanokouji sensei  are you   my kyou really wasn t bothering you   will you eventually return to the political arena  sensei   then  could you possibly keep my son by your side eventually  over sixty and still president of the ishigami group   gentle and polite despite high status  and openly dotes on his son kyou  hoping atsuomi will take him into politics rather than the family business  his son  worries he could almost be his grandson s age and would be too young to take over the company  holds him in high regard  asks him to mentor kyou","h":"<article class=\"card\" id=\"sc-ishigami-gorou-y0-p232-1\"><h3><span class=\"ttl\">President Ishigami, the doting father<\/span><span class=\"meta\">Side stories · p.232–233<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#ishigami-gorou\">Ishigami Gorou<\/a><\/span><\/h3><p class=\"setup\">Appears flustered after his son Ishigami is involved in the party dispute.<\/p><p class=\"with\">with <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ishigami Gorou<\/b> &quot;Hey, Kyou! You&#x27;re not causing any trouble for Ayanokouji-sensei, are you?&quot;<span class=\"pg\">p.232<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ishigami Gorou<\/b> &quot;My Kyou really wasn&#x27;t bothering you?&quot;<span class=\"pg\">p.232<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ishigami Gorou<\/b> &quot;Will you eventually return to the political arena, Sensei?&quot;<span class=\"pg\">p.233<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Then, could you possibly keep my son by your side eventually?&quot;<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Over sixty and still president of the Ishigami Group — gentle and polite despite high status, and openly dotes on his son Kyou, hoping Atsuomi will take him into politics rather than the family business.<span class=\"pg\">p.232–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> His son; worries he could almost be his grandson&#x27;s age and would be too young to take over the company.<span class=\"pg\">p.232–233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Holds him in high regard; asks him to mentor Kyou.<span class=\"pg\">p.232–233<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kanzaki-tomohiro-y0-p234-1","v":"y0","y":0,"o":36,"k":"narration","w":"kanzaki-ryuuji ayanokouji-kiyotaka kanzaki-tomohiro","q":"kanzaki tomohiro president kanzaki introduces his son introduces himself and his son ryuuji to atsuomi at the party   it s a great honor to meet you  i m kanzaki  kanzaki tomohiro from kanzaki engineering   this is my son  ryuuji  say hello   he s my pride and joy  i want him to excel in both academics and martial arts  and besides karate and judo  we ve also provided him with all possible education through cram schools and private teachers   in karate  he was even praised by the assistant instructor recently  he said that he has the skills of a black belt at this point already  a proud father of a relatively new company   had eagerly offered white room investment at launch and quietly invested a small amount two years later despite being declined  his son  boasts of his academic and martial arts education  investors mentor relationship  atsuomi s lecture to ryuuji keeps him from withdrawing investment","h":"<article class=\"card\" id=\"sc-kanzaki-tomohiro-y0-p234-1\"><h3><span class=\"ttl\">President Kanzaki introduces his son<\/span><span class=\"meta\">Side stories · p.234<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#kanzaki-tomohiro\">Kanzaki Tomohiro<\/a><\/span><\/h3><p class=\"setup\">Introduces himself and his son Ryuuji to Atsuomi at the party.<\/p><p class=\"with\">with <a href=\"../../../people/kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Kanzaki Tomohiro<\/b> &quot;It&#x27;s a great honor to meet you! I&#x27;m Kanzaki. Kanzaki Tomohiro from Kanzaki Engineering.&quot;<span class=\"pg\">p.234<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kanzaki Tomohiro<\/b> &quot;This is my son, Ryuuji. Say hello.&quot;<span class=\"pg\">p.234<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Kanzaki Tomohiro<\/b> &quot;He&#x27;s my pride and joy. I want him to excel in both academics and martial arts, and besides karate and judo, we&#x27;ve also provided him with all possible education through cram schools and private teachers.&quot;<span class=\"pg\">p.234<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;In karate, he was even praised by the assistant instructor recently. He said that he has the skills of a black belt at this point already.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> A proud father of a relatively new company — had eagerly offered White Room investment at launch and quietly invested a small amount two years later despite being declined.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> His son; boasts of his academic and martial-arts education.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Investors/mentor relationship; Atsuomi&#x27;s lecture to Ryuuji keeps him from withdrawing investment.<span class=\"pg\">p.234–237<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-suzukake-tanji-y0-p242-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-kiyotaka suzukake-tanji","q":"suzukake tanji suzukake s recorded reflections  march 11th  records a video on his phone  march 11th  on the day the white room is to be halted   today is march 11th  recorded by suzukake tanji   for a long time  i ve been in charge of the education in this white room   however  the white room will be halted for a while starting today   that child s  ayanokouji kiyotaka s presence is significant   truly a mutation   that child currently shows no upper limit to his talent   i wonder if that child i created  will grasp happiness at his dying moment  the white room halted due to naoe s maneuvering against atsuomi  suzukake takes the  extended vacation  positively  he introduced a communication curriculum from the fifth generation onward after realizing children seek communication even in a closed environment   it generated emotions but lowered the ability improvement rate  curriculum levels  fourth applied to fifth generation  fifth to sixth  sixth to seventh  all dropped out  then a mix of fourth fifth from the eighth  by the eighth year five children remained of the original seventy four   a  93  dropout rate  first third generation average 27  fifth onward 30  the cup bottle cap metaphor  an ordinary educator s talent is a bottle cap  white room educators a cup  children s limits scale to their educator s talent  true geniuses exceed the cup  bottle sized talent  but people with both exceptional talent and teaching skill are virtually nonexistent  the white room can make the top 10  but perhaps not the top 0 01  still believes punishment should be executed and emotions kept to a minimum  regards kiyotaka as a unique mutation  neither purely nature nor nurture  is driven crazy by not being able to prove why he survived without dropping out  doubts he is a true genius due to his lacking emotions and common knowledge  refuses to leave the final question of whether kiyotaka will grasp happiness on record  his most significant subject   a mutation with no upper limit  wonders if placing him as an instructor could raise the next generation s ceiling to the bottle s size","h":"<article class=\"card\" id=\"sc-suzukake-tanji-y0-p242-1\"><h3><span class=\"ttl\"><a href=\"../../../people/suzukake-tanji.html#sc-suzukake-tanji-y0-p242-1\">Suzukake&#x27;s recorded reflections (March 11th)<\/a><\/span><span class=\"meta\">Side stories · p.242–246<\/span><span class=\"by\">notes on <a href=\"../../../people/suzukake-tanji.html\">Suzukake Tanji<\/a><\/span><\/h3><p class=\"setup\">Records a video on his phone, March 11th, on the day the White Room is to be halted.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;TODAY IS MARCH 11th. Recorded by Suzukake Tanji.&quot;<span class=\"pg\">p.242<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;For a long time, I&#x27;ve been in charge of the education in this White Room.&quot;<span class=\"pg\">p.242<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Suzukake Tanji<\/b> &quot;However, the White Room will be halted for a while starting today.&quot;<span class=\"pg\">p.242<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;That child&#x27;s… Ayanokouji Kiyotaka&#x27;s presence is significant.&quot;<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Truly a mutation.&quot;<span class=\"pg\">p.243<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;That child currently shows no upper limit to his talent.&quot;<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I wonder if that child I created… will grasp happiness at his dying moment…&quot;<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The White Room halted due to Naoe&#x27;s maneuvering against Atsuomi; Suzukake takes the &quot;extended vacation&quot; positively.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> He introduced a communication curriculum from the fifth generation onward after realizing children seek communication even in a closed environment — it generated emotions but lowered the ability-improvement rate.<span class=\"pg\">p.242<\/span><\/li><li><span class=\"mlabel\">Numbers<\/span> Curriculum levels: fourth applied to fifth generation, fifth to sixth, sixth to seventh (all dropped out), then a mix of fourth/fifth from the eighth. By the eighth year five children remained of the original seventy-four — a &gt;93% dropout rate; first–third generation average 27%, fifth onward 30%.<span class=\"pg\">p.242–243<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> The cup/bottle-cap metaphor: an ordinary educator&#x27;s talent is a bottle cap, White Room educators a cup; children&#x27;s limits scale to their educator&#x27;s talent. True geniuses exceed the cup (bottle-sized talent), but people with both exceptional talent and teaching skill are virtually nonexistent; the White Room can make the top 10% but perhaps not the top 0.01%.<span class=\"pg\">p.243–245<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Still believes punishment should be executed and emotions kept to a minimum; regards Kiyotaka as a unique mutation, neither purely nature nor nurture; is driven crazy by not being able to prove why he survived without dropping out; doubts he is a true genius due to his lacking emotions and common knowledge; refuses to leave the final question of whether Kiyotaka will grasp happiness on record.<span class=\"pg\">p.243–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> His most significant subject — a mutation with no upper limit; wonders if placing him as an instructor could raise the next generation&#x27;s ceiling to the bottle&#x27;s size.<span class=\"pg\">p.243–246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-suzukake-tanji-y0-p126-1\">← Before: The Beta curriculum and Suzukake&#x27;s regret<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p247-1","v":"y0","y":0,"o":36,"k":"narration","w":"naoe-sensei kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi returning to tokyo  preparing the comeback returns to tokyo from saitama as cherry blossoms bloom  goes to his long unused office instead of his meguro home   you ve grown old  naoe  naoe  the fixer in kijima s shadow  is over eighty and was seriously ill   officially recovered but in reality his life hangs by a thread  his sabotage of the white room is proof he means to eliminate atsuomi before he dies   it s frustrating that i can t bury him with my own hands  but having him buried by illness might be best    kamogawa  that s why we need to make sure the timing is right when we go for the kill  sees the white room s freeze as a setback but readies a counterattack  notes kijima  in his sixties  could stay in power another ten or twenty years  making this  the last chance to strike  his old mentor is now an enemy dying by inches  atsuomi waits for his health to fail  meets him by the office  they discuss timing and naoe s deteriorating health","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p247-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p247-1\">Returning to Tokyo; preparing the comeback<\/a><\/span><span class=\"meta\">Side stories · p.247–250<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Returns to Tokyo from Saitama as cherry blossoms bloom; goes to his long-unused office instead of his Meguro home.<\/p><p class=\"with\">with <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;You&#x27;ve grown old, Naoe.&quot;<span class=\"pg\">p.247<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;It&#x27;s frustrating that I can&#x27;t bury him with my own hands, but having him buried by illness might be best.&quot; — Kamogawa<span class=\"pg\">p.249<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;That&#x27;s why we need to make sure the timing is right when we go for the kill.&quot;<span class=\"pg\">p.249<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Naoe, the fixer in Kijima&#x27;s shadow, is over eighty and was seriously ill — officially recovered but in reality his life hangs by a thread; his sabotage of the White Room is proof he means to eliminate Atsuomi before he dies.<span class=\"pg\">p.247<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sees the White Room&#x27;s freeze as a setback but readies a counterattack; notes Kijima (in his sixties) could stay in power another ten or twenty years, making this &quot;the last chance to strike.&quot;<span class=\"pg\">p.247–249<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">naoe-sensei<\/b> His old mentor is now an enemy dying by inches; Atsuomi waits for his health to fail.<span class=\"pg\">p.247–249<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Meets him by the office; they discuss timing and Naoe&#x27;s deteriorating health.<span class=\"pg\">p.247–249<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p232-1\">← Before: The children&#x27;s dispute; Kanzaki and Ishigami; Sakayanagi&#x27;s farewell<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p249-1\">→ After: Moving the children; the plan for Kiyotaka<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p249-1","v":"y0","y":0,"o":36,"k":"narration","w":"ayanokouji-atsuomi","q":"ayanokoji atsuomi moving the children  the plan for kiyotaka arranges the children s temporary supervision at a purchased orphanage and waits for kiyotaka to be brought from a counseling clinic   as planned  the children are temporarily being supervised and managed at the orphanage we purchased    tabuchi  i have no intention of favoring him just because he s my son   he s a monster  you shouldn t look at him with such a frivolous attitude    ishida kiyotaka was sent to the clinic because a major funder s daughter desperately wanted to meet him   atsuomi calls it a  shallow idea  that heals wounds in a counterproductive way  ishida calls kiyotaka a  monster  having watched him since birth  deliberately avoids favoritism toward his son in public  yet calls him the white room s  greatest masterpiece  with the  qualifications","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p249-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p249-1\">Moving the children; the plan for Kiyotaka<\/a><\/span><span class=\"meta\">Side stories · p.249–256<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Arranges the children&#x27;s temporary supervision at a purchased orphanage and waits for Kiyotaka to be brought from a counseling clinic.<\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;As planned, the children are temporarily being supervised and managed at the orphanage we purchased.&quot; — Tabuchi<span class=\"pg\">p.249<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;I have no intention of favoring him just because he&#x27;s my son.&quot;<span class=\"pg\">p.249<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;He&#x27;s a monster. You shouldn&#x27;t look at him with such a frivolous attitude.&quot; — Ishida<span class=\"pg\">p.250<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Kiyotaka was sent to the clinic because a major funder&#x27;s daughter desperately wanted to meet him — Atsuomi calls it a &quot;shallow idea&quot; that heals wounds in a counterproductive way; Ishida calls Kiyotaka a &quot;monster,&quot; having watched him since birth.<span class=\"pg\">p.250<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deliberately avoids favoritism toward his son in public, yet calls him the White Room&#x27;s &quot;greatest masterpiece&quot; with the &quot;qualifications.&quot;<span class=\"pg\">p.249–250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p247-1\">← Before: Returning to Tokyo; preparing the comeback<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p259-1\">→ After: The political plan; Tsukishiro enlisted<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y0-p251-1","v":"y0","y":0,"o":36,"k":"narration","w":"yuki ayanokouji-atsuomi kamogawa ishida-yuusuke ayanokouji-kiyotaka","q":"ayanokoji kiyotaka the yuki reunion  first day outside at a counseling clinic  meets a man in his early forties holding a vase of sakura flowers   kiyotaka s first time outside the white room after fourteen years   who are you   is that  sakura   yuki  i m yuki   why are you here   i ve been there for fourteen years  today is the first time i ve come outside   i have nothing to say   it s better if you stop  talking with me is impossible for you   then i refuse   nothing has changed since the time you ve disappeared   goodbye  it s better if we never meet again   nothing   understood  the man is yuki s father  she has grown weak  shut herself in  and could only be calmed by meeting a fellow fourth generation student   sakura is her favorite flower  her smile is  a bit awkward  but her emotions are rich  yuki trembles and hyperventilates recalling the white room  clings to his sleeve  her father blocks the exit and admits neither he  his wife nor his younger daughter can reach her  circumspect and cold   sees the meeting as  a meeting with the dead  declines to talk about the white room  refuses the father s personal request  it isn t  right  the white room representative didn t give me any specific instructions  and judges continued contact would only make yuki suffer  tells his father  nothing  about the outside scenery  deliberately letting him believe he feels no emotion    it was just easier to let him think everything was under control  in truth he is  constantly sharpening my fangs  his former white room classmate  refuses her desperate plea to talk  and leaves saying they should never meet again  his father  hides his true sharpening resolve from him  meets him in the car after leaving the clinic  doesn t respond to his greeting  ishida warns kamogawa that kiyotaka is a  monster","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y0-p251-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y0-p251-1\">The Yuki reunion; first day outside<\/a><\/span><span class=\"meta\">Side stories · p.251–258<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">At a counseling clinic, meets a man in his early forties holding a vase of sakura flowers — Kiyotaka&#x27;s first time outside the White Room after fourteen years.<\/p><p class=\"with\">with <a href=\"../../../people/yuki.html\">Yuki<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a> · <a href=\"../../../people/index.html#ishida-yuusuke\">Ishida Yūsuke<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Who are you?&quot;<span class=\"pg\">p.251<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Is that… sakura?&quot;<span class=\"pg\">p.251<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Yuki, I&#x27;m Yuki!&quot;<span class=\"pg\">p.252<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;Why are you here?&quot;<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I&#x27;ve been there for fourteen years. Today is the first time I&#x27;ve come outside.&quot;<span class=\"pg\">p.252<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;I have nothing to say.&quot;<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;It&#x27;s better if you stop. Talking with me is impossible for you.&quot;<span class=\"pg\">p.253<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Then I refuse.&quot;<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Nothing has changed since the time you&#x27;ve disappeared.&quot;<span class=\"pg\">p.254<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Goodbye. It&#x27;s better if we never meet again.&quot;<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Nothing.&quot;<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;Understood.&quot;<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> The man is Yuki&#x27;s father; she has grown weak, shut herself in, and could only be calmed by meeting a fellow fourth-generation student — sakura is her favorite flower. Her smile is &quot;a bit awkward&quot; but her emotions are rich.<span class=\"pg\">p.251–252<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Yuki trembles and hyperventilates recalling the White Room; clings to his sleeve; her father blocks the exit and admits neither he, his wife nor his younger daughter can reach her.<span class=\"pg\">p.252–254<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Circumspect and cold — sees the meeting as &quot;a meeting with the dead,&quot; declines to talk about the White Room, refuses the father&#x27;s personal request (&quot;It isn&#x27;t, right? The White Room representative didn&#x27;t give me any specific instructions&quot;), and judges continued contact would only make Yuki suffer.<span class=\"pg\">p.251–258<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Tells his father &quot;Nothing&quot; about the outside scenery, deliberately letting him believe he feels no emotion — &quot;it was just easier to let him think everything was under control&quot;; in truth he is &quot;constantly sharpening my fangs.&quot;<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yuki<\/b> His former White Room classmate; refuses her desperate plea to talk, and leaves saying they should never meet again.<span class=\"pg\">p.251–256<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> His father; hides his true sharpening resolve from him.<span class=\"pg\">p.256–258<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Meets him in the car after leaving the clinic; doesn&#x27;t respond to his greeting.<span class=\"pg\">p.256<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishida Yūsuke<\/b> Ishida warns Kamogawa that Kiyotaka is a &quot;monster.&quot;<span class=\"pg\">p.250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y0-p197-1\">← Before: The researchers on his lack of emotion<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-atsuomi-y0-p259-1","v":"y0","y":0,"o":36,"k":"narration","w":"tsukishiro kamogawa ayanokouji-atsuomi","q":"ayanokoji atsuomi the political plan  tsukishiro enlisted left alone with kamogawa after dropping kiyotaka off  lays out his political ambitions   it s the fact that the ultimate  perfected existence only exists in one person   it s frustrating that there s an age limit in the political world  it s the first time i ve felt this way   the earliest kiyotaka can become an elected official  after reaching adulthood  is at age twenty five  by then  i ll be sixty one   i haven t decided yet   if either i or kiyotaka can dominate the political scene  we could significantly change japan without having to discuss matters fifty or a hundred years into the future  weighing whether to make kiyotaka a politician   the  ultimate  perfected existence  exists in only one person  notes the disadvantage of nepotism and his son s lack of emotions and worldly knowledge  and begins preparing to change the plan and develop kiyotaka s individuality  enlisted to handle background arrangements  agrees to cooperate when atsuomi implements his plan  left in shock by the plan  kept close","h":"<article class=\"card\" id=\"sc-ayanokouji-atsuomi-y0-p259-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-atsuomi.html#sc-ayanokouji-atsuomi-y0-p259-1\">The political plan; Tsukishiro enlisted<\/a><\/span><span class=\"meta\">Side stories · p.259–260<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/span><\/h3><p class=\"setup\">Left alone with Kamogawa after dropping Kiyotaka off, lays out his political ambitions.<\/p><p class=\"with\">with <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/kamogawa.html\">Kamogawa<\/a><\/p><ul class=\"lines\"><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;It&#x27;s the fact that the ultimate, perfected existence only exists in one person.&quot;<span class=\"pg\">p.259<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;It&#x27;s frustrating that there&#x27;s an age limit in the political world; it&#x27;s the first time I&#x27;ve felt this way.&quot;<span class=\"pg\">p.259<\/span><\/li><li class=\"q narration\"><b class=\"sp\">Ayanokōji Atsuomi<\/b> &quot;The earliest Kiyotaka can become an elected official, after reaching adulthood, is at age twenty-five. By then, I&#x27;ll be sixty-one.&quot;<span class=\"pg\">p.259<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> &quot;I haven&#x27;t decided yet.&quot;<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> &quot;If either I or Kiyotaka can dominate the political scene, we could significantly change Japan without having to discuss matters fifty or a hundred years into the future.&quot;<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Weighing whether to make Kiyotaka a politician — the &quot;ultimate, perfected existence&quot; exists in only one person; notes the disadvantage of nepotism and his son&#x27;s lack of emotions and worldly knowledge, and begins preparing to change the plan and develop Kiyotaka&#x27;s individuality.<span class=\"pg\">p.259–260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Enlisted to handle background arrangements; agrees to cooperate when Atsuomi implements his plan.<span class=\"pg\">p.260–261<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamogawa<\/b> Left in shock by the plan; kept close.<span class=\"pg\">p.259–260<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-atsuomi-y0-p249-1\">← Before: Moving the children; the plan for Kiyotaka<\/button><\/div><\/article>"}];
